                ] : [
                    () => markIcon(mark, tone),
                    () => <div className="min-w-0 flex-1"><Typography size="sm" text={text ?? ""} /></div>,
                ]
            }
        />
    </li>
)
/**
 * Static "brief list" of MARKED rows (check / cross / none) in a bounded `bg-surface` card with
 * full-bleed dividers — a single list can mix marks (e.g. a plan's included check and excluded
 * cross features). Read-only; for CLICKABLE rows use {@link SurfaceCardList}.
 *
 * `isSkeleton` self-renders `skeletonRows` mirror rows (each row in its own skeleton
 * state) — consumer just flips the flag, no manual `<Skeleton>` assembly.
 *
 * @param props - {@link SurfaceCardCrossListProps}
 */
const CrossList = ({
    items,
    variant = "surface",
    isSkeleton = false,
    skeletonRows = 3,
    classNames,
    identity,
}: SurfaceCardCrossListProps) => (
    <ul
        className={cn("overflow-hidden", surfaceFrame(variant), classNames)}

        {...resolveIdentity(identity, { tier: "composite", name: "SurfaceCardCrossList" })}
    >
        {isSkeleton
            ? Array.from({ length: skeletonRows }).map((_, index) => (
                <CrossListRow key={index} isSkeleton />
            ))
            : items.map((item) => (
                <CrossListRow
                    key={item.key}
                    mark={item.mark}
                    tone={item.tone}
                    text={item.text}

                />
            ))}
    </ul>
)
// ─────────────────────────────────────────────────────────────────────────────
// .Placeholder — dashed "add new" tile (was `DashedPlaceholderCard`)
// ─────────────────────────────────────────────────────────────────────────────
/** Props for {@link SurfaceCardPlaceholder}. */
export interface SurfaceCardPlaceholderProps {
    /**
     * Decorative leading icon — a COMPONENT reference (COMPOSITE-8), never an
     * already-built element; the frame forces it to `size-8` (§4) to match the
     * label's tile-scale footprint. Defaults to {@link PlusIcon}.
     */
    icon?: ComponentType<SVGProps<SVGSVGElement>>
    /** Caption under the icon (e.g. "Create new CV"). The composite wraps it in `Typography` itself (COMPOSITE-8). */
    label: string
    /** Press handler — creates/opens the new item. */
    onPress: () => void
    /**
     * `true` → mark this tile as the CHOSEN one in a selectable grid — an
     * accent `ring-2 ring-accent`, same contract as `.Pressable`'s `isSelected`.
     * Rare (most callers just press it); available for parity with the rest
     * of the card family.
     */
    isSelected?: boolean
    /** Disables interaction and dims the tile (e.g. while the create mutation is in flight). */
    isDisabled?: boolean
    /**
     * `true` → render a generic skeleton mirror (same dashed-tile footprint,
     * icon + label swapped for shimmer) instead of the real press target.
     */
    isSkeleton?: boolean
    /** Where the tile sits inside its parent. Appearance is not passable — it is already a prop. */
    classNames?: Array<AllowedClassName>
    /**
     * Caller identity to wear on this composite's root instead of its own — pass this
     * when a block/layout/overlay/page uses this composite as its root element.
     * Omitted → this composite keeps emitting its own data-tier/data-component.
     */
    identity?: CallerIdentity
}
/**
 * Generic "add new" tile — a pressable, dashed-border `rounded-3xl` card with
 * a centered icon + label, muted. Fills the available height of its grid cell
 * (the tile itself is `h-full w-full`; the caller's grid row sets the height).
 *
 * Press contract §7: `active:scale` only, NO hover-bg — a dashed tile stays
 * quiet at rest and on hover, the only feedback is the press itself.
 *
 * @param props - {@link SurfaceCardPlaceholderProps}
 */
const Placeholder = ({
    icon: Icon = PlusIcon,
    label,
    onPress,
    isSelected = false,
    isDisabled = false,
    isSkeleton = false,
    classNames,
    identity,
}: SurfaceCardPlaceholderProps) => {
    // COMPOSITE-10: ONE render path — the tile keeps the same dashed frame, gap and
    // padding in both states; only the interactivity (button vs plain div, since
    // nothing is pressable yet while loading) and the label's shimmer differ. The
    // icon is CHROME the caller already picked at call-time (defaults to a plain
    // `PlusIcon`), not data arriving later, so it renders as-is unchanged either
    // way — the same convention `Nested`'s header `icon` uses elsewhere in this file.
    const shellClassName = cn(
        "flex h-full w-full flex-col items-center justify-center gap-1 rounded-3xl border-2 border-dashed border-default p-6",
        !isSkeleton && "text-center text-muted outline-none [-webkit-tap-highlight-color:transparent] transition-[scale] duration-200 ease-out motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-accent",
        !isSkeleton && isSelected && "ring-2 ring-accent",
        !isSkeleton && (isDisabled ? "cursor-not-allowed opacity-60" : "cursor-pointer active:scale-[0.97]"),
        classNames,
    )
    const tileBody = (
        <>
            {/* §4: the frame owns icon sizing — force the caller's bare icon to size-8. */}
            <span aria-hidden className="[&>svg]:size-8">
                <Icon />
            </span>
            <Typography size="sm" weight="medium" color="muted" isSkeleton={isSkeleton} text={label} />
        </>
    )
    if (isSkeleton) {
        return (
            <div
                data-principle="icon-text"
                className={shellClassName}
                {...resolveIdentity(identity, { tier: "composite", name: "SurfaceCardPlaceholder" })}
            >
                {tileBody}
            </div>
        )
    }
    return (
        <button
            type="button"
            onClick={onPress}
            disabled={isDisabled}
            aria-pressed={isSelected || undefined}
            {...resolveIdentity(identity, { tier: "composite", name: "SurfaceCardPlaceholder" })}
            data-principle="icon-text"
            className={shellClassName}
        >
            {tileBody}
        </button>
    )
}
/**
 * The card FRAME namespace — every bounded card surface of the design system,
 * one import, eight members. `.Pressable` isn't a separate member — `Base`
 * derives `isPressable` from `onPress`/`href` internally (see the file header).
 *
 * | Member | Content channel |
 * |---|---|
 * | `.Base` | `header`/`body`/`footer` slots (each a component reference, COMPOSITE-8) |
 * | `.Nested` | slots, or `items` (sections) |
 * | `.PressableGroup` | `items` |
 * | `.SelectableGroup` | `items` (single-select, `value`/`onChange`) |
 * | `.List` | `items` |
 * | `.Accordion` | `items` |
 * | `.CrossList` | `items` |
 * | `.Placeholder` | none (`icon`/`label`/`onPress`) |
 */
export { Base as SurfaceCard, Nested as SurfaceCardNested, PressableGroup as SurfaceCardPressableGroup, SelectableGroup as SurfaceCardSelectableGroup, List as SurfaceCardList, AccordionCard as SurfaceCardAccordion, CrossList as SurfaceCardCrossList, Placeholder as SurfaceCardPlaceholder }

import React from "react"
import { cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `Page.*` — the page-chrome frame namespace: the chrome of a ROUTE (what sits
 * above the content and pinned under it). Members are `PageHeader` and
 * `PageBottomBar`.
 *
 * `PageBottomBar` is a wrapper frame with named slots `body`/`actions`. `PageHeader` is not a generic wrapper — it owns semantic
 * slots (`breadcrumb`/`title`/`description`/`actions`/`meta`) and takes no
 * `children`. No repeating list, so no `items` member. Namespace only — no bare
 * component export.
 *
 * Both members own their own `isSkeleton`, so every slot they render is a component
 * reference (`ComponentType<{ isSkeleton?: boolean }>`) the frame calls itself to
 * forward the flag; text the frame renders directly through `Typography`
 * (`title`/`description`) is a plain `string`.
 */

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Page" } as const

// ─────────────────────────────────────────────────────────────────────────────
// .Header — the breadcrumb/title/description/actions/meta block (was `PageHeader`)
// ─────────────────────────────────────────────────────────────────────────────

/** Props {@link PageHeader} carries regardless of loading state. */
interface PageHeaderOwnProps {
    /**
     * Optional supporting description placed directly below the title. The
     * frame renders it through `Typography` itself (`text-sm`, muted tone) and
     * forwards `isSkeleton`, so this is plain text (COMPOSITE-8), not a
     * pre-built node. Omit when the title is self-explanatory.
     */
    description?: string
    /**
     * Optional breadcrumb row rendered above the title row, as a COMPONENT
     * reference (COMPOSITE-8) — the frame calls it itself. Typically a
     * `<Breadcrumbs>` house atom or a `LinkBack`. Omitted entirely while
     * loading (a route rarely needs it before data lands).
     */
    breadcrumb?: ComponentTypeWithSkeleton
    /**
     * Optional right-aligned slot for action controls, as a COMPONENT
     * reference — the frame calls it and renders it `shrink-0` so it never
     * compresses the title column. Omitted entirely while loading.
     */
    actions?: ComponentTypeWithSkeleton
    /**
     * Optional meta row placed BELOW the title/description — typically a row
     * of stat/meta chips ("24 Modules · 87 Content items …") — as a
     * COMPONENT reference. Rendered `gap-3` from the title block. While
     * loading, the frame draws its OWN 2-chip placeholder instead of calling
     * this (COMPOSITE-10: the frame decides how many, not this slot). Omit
     * when the header carries no stats.
     */
    meta?: ComponentTypeWithSkeleton
    /**
     * Title scale. `"page"` (default) = `Typography.Heading` level 3 — a route's
     * OWN page title. `"compact"` = body-size bold, for a header that labels a
     * PANE/PHASE inside an existing page shell.
     */
    size?: "page" | "compact"
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * `true` -> each part this frame renders carries a ``
     * attribute so a BlockAnatomy panel can badge it on-render. Off in production.
     */
}

/**
 * Props for {@link PageHeader}. `title` is REQUIRED unless `isSkeleton` (§12b) —
 * a shimmer header has no real title to show yet.
 */
export type PageHeaderProps = PageHeaderOwnProps &
    (
        | {
            isSkeleton: true
            /** Primary page or section title. See the live variant's doc for the full contract. */
            title?: string
        }
        | {
            isSkeleton?: false
            /**
             * Primary page or section title. Rendered at `text-xl font-medium` in the
             * foreground tone through `Typography` (COMPOSITE-8: the frame builds it
             * itself, so this is plain text).
             */
            title: string
        }
    )

/**
 * Page/section header frame. Renders an optional breadcrumb row above a flex
 * row that places a stacked title + description on the left and optional action
 * controls on the right.
 *
 * This frame carries no card wrapper — the caller places it directly inside
 * a `Container` or wraps it in a `SectionCard` when a framed surface
 * is required.
 *
 * @param props - See {@link PageHeaderProps}.
 */
const Header = ({
    title,
    description,
    breadcrumb: Breadcrumb,
    actions: Actions,
    meta: Meta,
    size = "page",
    isSkeleton = false,
    classNames,
}: PageHeaderProps) => {
    // ONE render path (§12c) — every part this frame would render anyway stays,
    // each handed `isSkeleton`; the atoms draw their own shimmer. While loading, the
    // real shape (breadcrumb/description/meta presence) isn't known yet, so the
    // composite makes the same shape call the old hand-split branch made: assume a
    // description line and a 2-chip meta row, skip breadcrumb/actions (a route
    // rarely needs those before data lands).
    const showDescription = isSkeleton || description != null
    const showMeta = isSkeleton || Meta != null

    // Left column: stacked title and optional description
    const titleBlock = (
        <>
            {size === "compact" ? (
                <Typography weight="bold" isSkeleton={isSkeleton} text={title} />
            ) : (
                <Typography size="h3" weight="bold" isSkeleton={isSkeleton} text={title} />
            )}
            {showDescription ? (
                // clamp to 2 lines on mobile (keep the header short on a phone); full on sm+
                // — a viewport-width decision, so the wrapper owns it, not the atom.
                <div className={isSkeleton ? undefined : "line-clamp-2 @app-sm:line-clamp-none"}>
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}
                    />
                </div>
            ) : null}
        </>
    )
    // Main row: title+description stack on the left, actions pinned to the right
    const titleRow = (
        <StackH
            align="start"
            justify="between"
            gap={4}
            principle="content-row"
            isSkeleton={isSkeleton}
            items={[
                () => <StackV gap={3} classNames={["min-w-0"]} isSkeleton={isSkeleton} items={[() => titleBlock]} />,
                // Right slot: shrink-0 prevents action buttons from being squeezed.
                // Omitted while loading — the shape of the action row isn't known yet.
                ...(!isSkeleton && Actions ? [() => (
                    <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>
                )] : []),
            ]}
        />
    )
    const headerBody = (
        <>
            {/* Breadcrumb row — rendered only when provided and loaded, sits above the main title row */}
            {!isSkeleton && Breadcrumb ? (
                <div><Breadcrumb isSkeleton={isSkeleton} /></div>
            ) : null}
            {titleRow}
            {/* Meta row: stat/meta chips below the title block (gap={4} from outer). While
                loading, 2 `Chip` placeholders stand in — the composite decides the count,
                the atom draws its own pill shimmer (no hand-rolled bar). */}
            {showMeta ? (
                isSkeleton ? (
                    <StackH
                        gap={3}
                        align="stretch"
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        isSkeleton={isSkeleton}
                        items={[
                            () => <Chip isSkeleton />,
                            () => <Chip isSkeleton />,
                        ]}
                    />
                ) : (
                    <div>{Meta ? <Meta isSkeleton={isSkeleton} /> : null}</div>
                )
            ) : null}
        </>
    )
    return (
        // outer gap={4}: breadcrumb <-> title-block <-> meta (different header tiers);
        // title <-> description stay a related gap={3} pair inside the title block.
        <StackV gap={4} classNames={classNames} isSkeleton={isSkeleton} items={[() => headerBody]} />
    )
}

// ─────────────────────────────────────────────────────────────────────────────
// .BottomBar — the viewport-pinned action bar (was `StickyBottomBar`)
// ─────────────────────────────────────────────────────────────────────────────

/** Props for {@link PageBottomBar}. */
export interface PageBottomBarProps {
    /**
     * Leading content of the bar — typically a price — as a COMPONENT
     * reference (COMPOSITE-8): the frame calls it itself so it can forward
     * `isSkeleton`.
     */
    body?: ComponentTypeWithSkeleton
    /**
     * Trailing control(s) — the primary CTA — as a COMPONENT reference. When
     * BOTH `body` and `actions` are given the frame lays out the row itself
     * (`justify-between`, `shrink-0` on the actions) so callers stop
     * hand-rolling that flex row.
     */
    actions?: ComponentTypeWithSkeleton
    /** Shorthand for {@link PageBottomBarProps.body} — same component-reference contract. */
    /**
     * `true` -> forwarded into whichever of `body`/`actions` renders, so a bar
     * whose price/CTA is not known yet (e.g. still loading enrollment status)
     * can shimmer instead of showing stale content.
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * `true` -> each region emits `` so a BlockAnatomy
     * panel can badge it on-render. Off in production.
     */
}

/**
 * A fixed bottom action bar pinned to the viewport edge — owns the chrome
 * (fixed position, top divider, surface background, safe padding) so features
 * just drop a price + CTA inside. Typically `@app-md:hidden` for a mobile sticky
 * enroll/checkout bar.
 *
 * A bar is a horizontal row, so its named slots are `body` (leading) +
 * `actions` (trailing) rather than the vertical `header`/`body`/`footer` trio.
 * With only one of them the content renders RAW, so a full-width button or a
 * two-button decision row keeps its own sizing (`flex-1`, `w-full`).
 *
 * @param props - {@link PageBottomBarProps}
 */
const BottomBar = ({
    body,
    actions,
    isSkeleton = false,
    classNames,
}: PageBottomBarProps) => {
    const Main = body
    const Actions = actions
    const chrome = "fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 border-t border-separator bg-background px-6 py-3"

    // Only ONE side supplied -> render it raw: the caller's own width strategy
    // (`w-full` CTA, two `flex-1` buttons) must not be boxed by a shrink-0 wrapper.
    if (Main == null || Actions == null) {
        const Only = Main ?? Actions
        return (
            <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
                <div>{Only ? <Only isSkeleton={isSkeleton} /> : null}</div>
            </div>
        )
    }

    return (
        <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
            <StackH
                align="center"
                justify="between"
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                isSkeleton={isSkeleton}
                items={[
                    () => <div className="min-w-0"><Main isSkeleton={isSkeleton} /></div>,
                    () => <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>,
                ]}
            />
        </div>
    )
}

/**
 * Page chrome members — a route imports these by name:
 *
 * | Export | Content channel |
 * |---|---|
 * | `PageHeader` | `breadcrumb`/`title`/`description`/`actions`/`meta` (no children) |
 * | `PageBottomBar` | `body`/`actions` slots |
 */
export { Header as PageHeader, BottomBar as PageBottomBar }

import React from "react"
import type { ReactNode } from "react"
import { Skeleton as HeroSkeleton, cn } from "@heroui/react"
import { ArrowRightIcon, LockIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { IconTile } from "@sb-components/atoms/display/IconTile/IconTile"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Box } from "@sb-components/frames/Box/Box"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { PhaseScarcityNote, type PricingPhase } from "@sb-components/starci/blocks/commerce/PhaseScarcityNote/PhaseScarcityNote"
import { PriceTagProminent, type PriceBreakdown } from "@sb-components/starci/blocks/commerce/PriceTag/PriceTag"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `EnrollGate` — the conversion card shown in place of an enrollment-required
 * learn surface (currently personal-project) for a trial viewer. Kept separate
 * from `ContentPaywall` despite composing the same two commerce blocks. Four
 * leaves: `Standalone` (no `preview`, centered), `WithPreview` (floats over a
 * faded teaser), `NoScarcity` (no `price.currentPhase`, drops
 * `PhaseScarcityNote`), and `Loading` (`isSkeleton`, price region shimmers).
 */

/**
 * Named price shape for {@link EnrollGateProps.price} — see the file header's
 * "THE `price` PROP IS A NEW NAME" note for why this isn't just `PriceBreakdown`.
 */
export interface EnrollGatePrice {
    /** Price the learner actually pays, in VND. */
    discountedVnd: number
    /** Pre-discount VND price; `PriceTagProminent` strikes it through when greater. */
    originalVnd?: number | null
    /** Phase-tier + loyalty steps for `PriceTagProminent`'s breakdown popover. */
    breakdown?: PriceBreakdown
    /** Current pricing phase — drives the scarcity line. Omit → no scarcity line. */
    currentPhase?: PricingPhase
    /** Seats left in the current phase. `null`/omitted → unlimited, scarcity line stays silent. */
    seatsRemaining?: number | null
    /** What the next phase will cost — the honest "waiting is not free" fact. */
    nextPhasePriceVnd?: number | null
}

/** Props for {@link EnrollGate}. */
export interface EnrollGateProps {
    /** Headline, localized by the caller — e.g. "Unlock Personal Project". */
    title: string
    /** One-line reason the surface needs enrollment. */
    description: string
    /**
     * Optional MOCK teaser of the gated surface (e.g. `PersonalProjectGatePreview`)
     * — non-interactive, rendered `aria-hidden` behind a bottom fade with the
     * enroll card floating over it. Omit → just the centered enroll card.
     */
    preview?: ReactNode
    /**
     * Resolved price + scarcity data. `undefined` → the price region shows the
     * `AsyncContent` shimmer (not yet resolved); the lock/headline/description/CTA
     * stay real regardless.
     */
    price?: EnrollGatePrice
    /** Fired when the learner takes the enroll CTA. */
    onEnroll: () => void
    /**
     * `true` → force the price region into its shimmer state even if `price` is
     * already known (used by this block's own "Loading" story state). The lock,
     * headline, description and CTA never shimmer — see the file header.
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     * Prefer this over `className`; the string form is going away.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * The conversion card in front of a gated learn surface. See the file header
 * for the full contract.
 *
 * @param props - {@link EnrollGateProps}
 */
const EnrollGateBase = ({
    title,
    description,
    preview,
    price,
    onEnroll,
    isSkeleton = false,
    classNames,
}: EnrollGateProps) => {
    // no price to show yet (unresolved) OR the caller forces the loading state —
    // either way the price region falls to the AsyncContent shimmer branch.
    const priceLoading = isSkeleton || price == null

    // The price group only exists once `price` has resolved — kept as its own
    // named const because it depends on `price` and is only used inside the
    // `AsyncContent` content branch below.
    const priceGroup = price != null ? (
        <>
            <PriceTagProminent
                discounted={price.discountedVnd}
                original={price.originalVnd}
                breakdown={price.breakdown}
                classNames={["self-center"]}
            />
            {price.currentPhase != null ? (
                <Box className="self-center">
                    <PhaseScarcityNote
                        currentPhase={price.currentPhase}
                        seatsRemaining={price.seatsRemaining ?? null}
                        nextPhasePriceVnd={price.nextPhasePriceVnd ?? null}
                    />
                </Box>
            ) : null}
        </>
    ) : null

    // lock identity + outcome copy + price + scarcity + one CTA — everything
    // the conversion card's own `StackV` arranges.
    const offerBody = (
        <>
            <IconTile
                icon={LockIcon}
                tone="accent"
                size="sm"

            />
            {/* the real src (`EnrollGate/index.tsx:67`): `type="h4" weight="bold"` — a real
                HEADING (20px), not body `lg` (18px). */}
            <Typography
                size="h4"
                weight="bold"
                align="center"
                text={title}

            />
            <Typography
                size="sm"
                color="muted"
                align="center"
                text={description}

            />
            <AsyncContent
                isLoading={priceLoading}
                skeleton={() => <HeroSkeleton className="h-7 w-32 rounded-xl" />}
                content={() => <StackV gap={4} principle="card-caption"
                    explain="Holds caption text under card media so the caption stays attached to the image above it."
                    align="center" isSkeleton={isSkeleton} items={[() => priceGroup]} />}
            />
            <Button
                label="Enroll now"
                variant="primary"
                size="lg"
                suffixIcon={ArrowRightIcon}
                iconSlide
                onPress={onEnroll}


            />
        </>
    )

    // the conversion card itself: lock identity + outcome copy + price + scarcity
    // + one CTA. A real SurfaceCard so it "floats up" whether it sits alone on
    // the canvas or over the faded teaser.
    const card = (
        // `SurfaceCard.className` door was deleted (COMPOSITE-4) and `max-w-[480px]` is an
        // arbitrary value outside the closed `AllowedClassName` union anyway — no frame's
        // typed `classNames` can carry it. `Box` centres via `principle="center-measure"`
        // (the real `mx-auto`) and keeps the raw width class as its escape-hatch `className`.
        // TODO(atom): `max-w-[480px]` still wants its own typed sizing step (or a matching
        // `Container` size) so this card stops needing the escape hatch at all.
        <Box principle="center-measure"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            className="w-full max-w-[480px]">
            <SurfaceCard
                padding={6}

                body={() => <StackV gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center" isSkeleton={isSkeleton} items={[() => offerBody]} />}
            />
        </Box>
    )

    // no teaser → just the centered enroll card. `StackH` with a single child and
    // `gap={1}` (no seam to enforce with one item) is how the §10 scale still
    // governs the wrapper's padding instead of a hand-typed `p-*` value.
    if (preview == null) {
        return (
            <StackH gap={1} principle="page-pad"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                justify="center" padding={6} isSkeleton={isSkeleton} classNames={classNames} items={[() => card]}  />
        )
    }

    // teaser → the FULL preview (no height cap — mirrors `ContentArticle`, which
    // renders the whole real body and only fades its tail, never truncates
    // early), with the enroll card floating over the faded tail.
    return (
        <div className={cn("relative", classNames)}>
            <div aria-hidden className="pointer-events-none relative">
                {preview}
                {/* Same fade band as `ContentArticle`'s locked-body tail — fades into
                    the preview's OWN card token (`bg-surface`), not the page canvas,
                    since the teaser content is itself `bg-surface` cards. */}
                <div className="absolute inset-x-0 bottom-0 h-72 bg-gradient-to-b from-transparent via-surface/70 to-surface" />
            </div>
            {/* `padding={6}` (the frame's own §10c scale) replaces the hand-typed
                `px-4 pb-6` the real component used — the ONE deviation from a byte-for-byte
                port, since the scale is symmetric and has no asymmetric step. `-mt-32` stays
                hand-written: it is the float-over-the-fade OVERLAP effect itself, not a seam
                between siblings, the same idiom as `SurfaceCard.Pressable`'s highlight layer. */}
            <div className="relative z-10 -mt-32">
                <StackH gap={1} principle="page-pad"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                    justify="center" padding={6} isSkeleton={isSkeleton} items={[() => card]}  />
            </div>
        </div>
    )
}

/** `EnrollGate.*` — single-component namespace ⇒ only `.Base`. */
export { EnrollGateBase as EnrollGate }

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { LinkBack } from "@/components/atoms/navigation/Link"
import { Typography } from "@/components/atoms/text/Typography"
import { PageHeader } from "@/components/composites/layout/Page"
import { StackH } from "@/components/frames/Stack"

/**
 * `ChallengeHeader` — the challenge-identity cluster atop the solve page: back
 * link, title, optional description, and a meta row carrying score, difficulty,
 * and the learner's pass-fail status. A `PageHeader` cluster. Two chips on
 * purpose — `difficulty` (a property of the challenge) and `status` (a property
 * of the attempt) are separate axes. Whether the status chip draws, and loading,
 * are data.
 */

/** How hard the challenge is — a property of the CHALLENGE, always known. */
export type ChallengeDifficulty = "easy" | "medium" | "hard"

/** Where the learner's own attempt stands — a property of the ATTEMPT, may not exist yet. */
export type ChallengeStatus = "completed" | "failed" | "inProgress"

/** Difficulty → chip presentation. The block owns this table (§14d.1: no caller-supplied color). */
const DIFFICULTY_MAP: Record<ChallengeDifficulty, EnumChipEntry> = {
    easy: { color: "success", label: "Easy" },
    medium: { color: "warning", label: "Medium" },
    hard: { color: "danger", label: "Hard" },
}

/**
 * Attempt status → chip presentation.
 *
 * `failed` gets a leading icon — a failed/not-passed verdict is a "universal"
 * symbol (cross), not decoration. `completed`/`inProgress` stay text-only; extend
 * the day a screen actually asks for their icon too, not preemptively.
 */
const STATUS_MAP: Record<ChallengeStatus, EnumChipEntry> = {
    completed: { color: "success", label: "Passed" },
    failed: { color: "danger", label: "Failed", icon: "cross" },
    inProgress: { color: "warning", label: "In progress" },
}

/** Props for {@link ChallengeHeader}. */
export interface ChallengeHeaderProps {
    /** Fired when the back link is pressed — the block never owns routing, only the affordance. */
    onBackPress: () => void
    /** Full back-link label override; omit to fall back to `LinkBack`'s generic "Back". */
    backLabel?: string
    /** Challenge title. */
    title: string
    /** One-sentence summary of the challenge. */
    description?: string
    /**
     * Points this challenge is worth, in RAW NUMBER — the block adds the unit
     * itself ("{n} points", §14d.1). Omit when no score is defined yet.
     */
    scoreValue?: number
    /**
     * How hard the challenge is. Always required — every challenge has a fixed
     * difficulty tier independent of whether the learner has attempted it yet.
     */
    difficulty: ChallengeDifficulty
    /**
     * The learner's own attempt outcome. Omit when the learner has not
     * attempted this challenge — the status chip is not drawn at all rather
     * than showing a "not started" chip nobody asked for.
     */
    status?: ChallengeStatus
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The challenge identity cluster at the top of the solve page. See the file
 * header for why it is a sibling of `ContentHeader` rather than an edit of it.
 *
 * @param props - {@link ChallengeHeaderProps}
 */
const ChallengeHeader = ({
    onBackPress,
    backLabel,
    title,
    description,
    scoreValue,
    difficulty,
    status,
    isSkeleton = false,
}: ChallengeHeaderProps) => {
    // ONE row, all with the same `gap={3}`, sitting close together on the left:
    // CHIPS FIRST (status, difficulty) then the score as plain text. No
    // `prefixIcon={TrophyIcon}`, and status comes before difficulty.
    const metaRow = (
        <>
            {isSkeleton ? (
                <EnumChip
                    value="inProgress"
                    map={STATUS_MAP}
                    isSkeleton

                />
            ) : status != null ? (
                <EnumChip
                    value={status}
                    map={STATUS_MAP}

                />
            ) : null}
            {isSkeleton ? (
                <EnumChip
                    value="easy"
                    map={DIFFICULTY_MAP}
                    isSkeleton

                />
            ) : (
                <EnumChip
                    value={difficulty}
                    map={DIFFICULTY_MAP}

                />
            )}
            {isSkeleton ? (
                <Typography size="xs" color="muted" isSkeleton classNames={["w-1/4"]} />
            ) : scoreValue != null ? (
                <Typography
                    size="xs"
                    color="muted"
                    text={`${scoreValue} points`}

                />
            ) : null}
        </>
    )

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <LinkBack
                        label={backLabel}
                        onPress={onBackPress}
                        isSkeleton={isSkeleton}
                    />
                )}
                title={title}
                // `PageHeader.description` is now a plain `string` (COMPOSITE-4), so this
                // block no longer wraps it in `RichText` at the call site — the field is
                // already typed/documented as a plain one-sentence summary, never markdown,
                // and `PageHeader` now owns the muted styling + skeleton swap itself.
                description={description}
                meta={({ isSkeleton }: SkeletonProps) =>
                    <StackH gap={3} align="center" principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        isSkeleton={isSkeleton} items={[() => metaRow]}  />
                }
            />
        </div>
    )
}

export { ChallengeHeader }

import { InputTextarea } from "@/components/atoms/forms"
import React, { useState } from "react"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Button } from "@/components/atoms/buttons/Button"

import { InputButtonLike } from "@/components/composites/buttons/InputButtonLike"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK — `ContentCommentComposer`: the textarea + submit control for new
 * comments, replies, and edits — ONE component, three call shapes, ported
 * verbatim from real `src`'s `CommentComposer`. See the component's own file
 * header for why `variant="primary"` (real `Discussion` is frameless — no
 * card ever wraps this field) and why the avatar-led row is top-level only.
 *
 * LEAVES by STRUCTURE (§14d.2). Collapsed-pill vs expanded-field is a real
 * node swap => separate leaves. Avatar present/absent is also a node swap
 * (top-level vs reply/edit) => its own leaf.
 */

/** Minimal identity for the avatar-led top-level composer. */
export interface ContentCommentComposerViewer {
    username: string
    avatarUrl?: string
}

/** Props for {@link ContentCommentComposer}. */
export interface ContentCommentComposerProps {
    /** Called with the trimmed body when the reader submits a non-empty comment. */
    onSubmit: (body: string) => void
    /** Placeholder text for the field. */
    placeholder?: string
    /** Submit button label. */
    submitLabel?: string
    /** Optional cancel handler — renders a cancel button when provided (reply/edit). */
    onCancel?: () => void
    /** Initial field value (editing an existing comment). */
    initialValue?: string
    /** `true` -> submit is disabled and shows its busy affordance. */
    isPending?: boolean
    /**
 * Set -> the composer is avatar-led (top-level only; reply/edit omit this).
 * `null` -> signed-out top-level composer, no avatar.
 */
    currentUser?: ContentCommentComposerViewer | null
    /**
 * `true` -> starts collapsed as a slim avatar + placeholder pill, expands to
 * the full field on click (the top-level composer pattern). Reply/edit
 * composers omit this and render expanded.
 */
    collapsible?: boolean
    /** Accessible name for the field. */
    ariaLabel: string
    /** Where this sits inside its parent (placement only, e.g. `flex-1` beside a `ThreadConnector`). */
    classNames?: Array<AllowedClassName>
}

/**
 * The comment/reply/edit composer. See the file header for the full contract.
 *
 * @param props - {@link ContentCommentComposerProps}
 */
const ContentCommentComposer = ({
    onSubmit: onSubmitAction,
    placeholder = "Ask a question or share your thoughts…",
    submitLabel = "Post",
    onCancel: onCancelAction,
    initialValue,
    isPending = false,
    currentUser,
    collapsible = false,
    ariaLabel,
    classNames,
}: ContentCommentComposerProps) => {
    const [body, setBody] = useState(initialValue ?? "")
    // collapsible composers start closed; reply/edit always render expanded
    const [expanded, setExpanded] = useState(!collapsible)
    const trimmed = body.trim()

    const onSubmit = () => {
        if (!trimmed) {
            return
        }
        onSubmitAction(trimmed)
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
    }

    const onCancel = () => {
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
        onCancelAction?.()
    }

    // collapsed pill: avatar + placeholder, the whole row opens the composer
    if (collapsible && !expanded) {
        return (
            <StackH identity={{ tier: "block", component: "ContentCommentComposer" }}
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"

                items={[
                    ...(currentUser ? [() => (
                        <Avatar src={currentUser.avatarUrl} name={currentUser.username} seed={currentUser.username} size="sm" />
                    )] : []),
                    () => (
                        <div className="min-w-0 flex-1">
                            <InputButtonLike
                                placeholder={placeholder}
                                ariaLabel={ariaLabel}
                                onPress={() => setExpanded(true)}
                            />
                        </div>
                    ),
                ]}
            />
        )
    }

    const buttonRow = (
        <>
            <Button
                label={submitLabel}
                size="sm"
                onPress={onSubmit}
                isDisabled={!trimmed}
                isPending={isPending}

            />
            {onCancelAction || collapsible ? (
                <Button
                    label="Cancel"
                    variant="tertiary"
                    size="sm"
                    onPress={onCancel}
                    isDisabled={isPending}

                />
            ) : null}
        </>
    )

    const fieldColumn = (
        <>
            <InputTextarea
                value={body}
                onValueChange={setBody}
                placeholder={placeholder}
                ariaLabel={ariaLabel}
                rows={3}
                variant="primary"

            />
            <StackH gap={3} items={[() => buttonRow]} />
        </>
    )

    const composerRow = (
        <>
            {currentUser ? (
                <Avatar src={currentUser.avatarUrl} name={currentUser.username} seed={currentUser.username} size="sm" />
            ) : null}
            <StackV gap={3} classNames={["min-w-0", "flex-1"]} items={[() => fieldColumn]} />
        </>
    )

    return (
        <StackH identity={{ tier: "block", component: "ContentCommentComposer" }} gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start" classNames={classNames} items={[() => composerRow]}  />
    )
}

export { ContentCommentComposer }

import React, { useState } from "react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { ThreadConnector } from "@/components/atoms/display/ThreadConnector"
import { Typography } from "@/components/atoms/text/Typography"
import { IdentityContentRow } from "@/components/composites/lists/IdentityContentRow"
import { StackH, StackV } from "@/components/frames/Stack"
import { ContentCommentComposer, type ContentCommentComposerViewer } from "@/components/blocks/learn/ContentCommentComposer"
import { ReactionButton, type ReactionType, type ReactionCount } from "@/components/blocks/learn/ReactionButton"

/**
 * BLOCK — `ContentCommentThread`: one threaded comment — author, reaction,
 * reply/edit/delete actions, and its recursively-rendered replies. Ported
 * verbatim from real `src`'s `CommentItem`. See the component's own file
 * header for the massive gap this fills against the earlier flat-list cut.
 *
 * 📐 LEAVES by STRUCTURE (§14d.2). Owner-only actions appearing, the body
 * swapping for an edit composer or a deleted placeholder, and the reply
 * subtree expanding each add/remove real nodes ⇒ separate leaves.
 */

/** Minimal identity for a comment's author. */
export interface ContentCommentAuthor {
    id: string
    username: string
    avatarUrl?: string
}

/** One comment (or, at `depth > 0`, one reply). */
export interface ContentCommentNode {
    /** Stable id — also what reply/edit/delete/react target. */
    id: string
    author: ContentCommentAuthor
    /** Already-formatted relative time, e.g. "2 hours ago". */
    createdTimeAgo: string
    /** `true` → a founder badge rides beside the author name. */
    isFounderAuthor?: boolean
    /** `true` → the body was edited after posting; shows a quiet "(edited)" marker. */
    isEdited?: boolean
    /** `true` → the body is replaced with a "removed" placeholder; no actions render. */
    isDeleted?: boolean
    /** The comment text (ignored when `isDeleted`). */
    body: string
    /** Total replies under this comment (drives the "view replies" toggle). */
    replyCount: number
    /** The viewer's own reaction on this comment, or `null`. */
    myReaction: ReactionType | null
    /** Per-emotion reaction counts on this comment. */
    reactionCounts?: ReadonlyArray<ReactionCount>
}

/** Callbacks shared down the comment tree — same shape at every depth. */
export interface ContentCommentThreadCallbacks {
    onReply: (parentId: string, body: string) => void
    onEdit: (commentId: string, body: string) => void
    onDelete: (commentId: string) => void
    onReactComment: (commentId: string, type: ReactionType | null) => void
    /** Lazily load a parent's replies — fired the first time its subtree expands. */
    onLoadReplies: (parentId: string) => void
}

/** Props for the module-scope {@link CommentByline} helper. */
interface CommentBylineProps {
    username: string
    isFounderAuthor?: boolean
    createdTimeAgo: string
    isEdited?: boolean
}

/**
 * `IdentityContentRow.byline` — a component reference (COMPOSITE-8), not a
 * built element. Kept at MODULE scope (not defined inline inside
 * `ContentCommentThread`'s body) and fed only read-only per-comment fields as
 * props, so passing a fresh wrapping arrow each render never risks remounting
 * anything stateful — there is no state in this leaf to lose.
 */
const CommentByline = ({ username, isFounderAuthor, createdTimeAgo, isEdited }: CommentBylineProps) => (
    <StackH
        gap={2}
        principle="separator-dot"
        explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
        align="center"
        items={[
            () => (
                <StackH
                    gap={2}
                    principle="icon-text"
                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                    align="center"
                    items={[
                        () => <Typography size="sm" weight="medium" text={username} />,
                        ...(isFounderAuthor ? [() => (
                            <SealCheckIcon weight="fill" aria-label="Founder" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                        )] : []),
                    ]}
                />
            ),
            () => <Typography size="xs" color="muted" text={createdTimeAgo} />,
            ...(isEdited ? [() => (
                <Typography size="xs" color="muted" text="(edited)" />
            )] : []),
        ]}
    />
)

/** Props for {@link ContentCommentThread}. */
export interface ContentCommentThreadProps extends ContentCommentThreadCallbacks {
    /** The comment to render. */
    comment: ContentCommentNode
    /** Current viewer id — drives owner-only edit/delete; null when signed out. */
    currentUserId: string | null
    /**
     * Current viewer identity for the reply composer's own avatar (Facebook-style
     * nested reply) — `null`/omitted → reply composer renders with no avatar. Real
     * `CommentComposer` never shows one at all; this is a deliberate divergence, not
     * a `src` port.
     */
    currentUser?: ContentCommentComposerViewer | null
    /** Nesting depth — 0 for a top-level comment, `depth + 1` for each reply. */
    depth: number
    /** Already-loaded replies, keyed by parent id (empty until `onLoadReplies` resolves). */
    repliesByParent: Record<string, ReadonlyArray<ContentCommentNode>>
}

/**
 * One threaded comment. See the file header for the full contract.
 *
 * @param props - {@link ContentCommentThreadProps}
 */
const ContentCommentThread = ({
    comment,
    currentUserId,
    currentUser,
    depth,
    repliesByParent,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies,
}: ContentCommentThreadProps) => {
    const [replying, setReplying] = useState(false)
    const [editing, setEditing] = useState(false)
    const [expanded, setExpanded] = useState(false)

    const isOwner = currentUserId !== null && currentUserId === comment.author.id
    const replies = repliesByParent[comment.id] ?? []

    const toggleReplies = () => {
        const next = !expanded
        setExpanded(next)
        if (next) {
            onLoadReplies(comment.id)
        }
    }

    // action row: reaction + reply + owner edit/delete. `isButton`, NOT `isLink` — real
    // src's own action links carry no underline at all, only a resting→hover COLOR
    // shift, which isLink's underline treatment would misrepresent.
    const actionRow = (
        <>
            <ReactionButton
                myReaction={comment.myReaction}
                counts={comment.reactionCounts}
                onReact={(type) => onReactComment(comment.id, type)}


            />
            <Typography
                size="xs"
                weight="medium"
                color="muted"
                isButton
                hoverColor="default"
                text="Reply"
                onPress={() => setReplying((prev) => !prev)}

            />
            {isOwner ? (
                <>
                    <Typography
                        size="xs"
                        weight="medium"
                        color="muted"
                        isButton
                        hoverColor="default"
                        text="Edit"
                        onPress={() => setEditing(true)}

                    />
                    <Typography
                        size="xs"
                        weight="medium"
                        color="muted"
                        isButton
                        hoverColor="danger"
                        text="Delete"
                        onPress={() => onDelete(comment.id)}

                    />
                </>
            ) : null}
        </>
    )

    const bodyAndActions = (
        <>
            {/* body, edit form, or deleted placeholder */}
            {comment.isDeleted ? (
                <Typography size="sm" color="muted" isItalic text="[Comment removed]" />
            ) : editing ? (
                <ContentCommentComposer
                    initialValue={comment.body}
                    submitLabel="Save"
                    ariaLabel="Edit comment"
                    onCancel={() => setEditing(false)}
                    onSubmit={(body) => {
                        onEdit(comment.id, body)
                        setEditing(false)
                    }}

                />
            ) : (
                <Typography size="sm" preserveWhitespace text={comment.body} />
            )}

            {!comment.isDeleted && !editing ? (
                <StackH gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    at="sm" align="center" items={[() => actionRow]}  />
            ) : null}
        </>
    )

    const threadBody = (
        <>
            <StackV gap={2} items={[() => bodyAndActions]} />

            {/* reply composer — `ThreadConnector` draws the Facebook-style curved
                guide from this comment down into the reply's own avatar;
                `currentUser` is what gives the composer an avatar to connect TO
                in the first place (see its own file header). */}
            {replying ? (
                <StackH
                    gap={2}
                    principle="icon-text"
                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                    align="start"

                    items={[
                        () => <ThreadConnector />,
                        () => (
                            <ContentCommentComposer
                                placeholder="Write a reply..."
                                submitLabel="Reply"
                                ariaLabel="Write a reply"
                                currentUser={currentUser}
                                classNames={["min-w-0", "flex-1"]}
                                onCancel={() => setReplying(false)}
                                onSubmit={(body) => {
                                    onReply(comment.id, body)
                                    setReplying(false)
                                    setExpanded(true)
                                    onLoadReplies(comment.id)
                                }}

                            />
                        ),
                    ]}
                />
            ) : null}

            {/* replies toggle + recursive subtree */}
            {comment.replyCount > 0 ? (
                <Typography
                    size="xs"
                    weight="medium"
                    color="accent"
                    isLink
                    underlineOnHover
                    text={expanded ? "Hide replies" : `View ${comment.replyCount} replies`}
                    onPress={toggleReplies}

                />
            ) : null}

            {expanded && replies.length > 0 ? (
                <StackV
                    gap={4}

                    items={replies.map((reply) => () => (
                        <ContentCommentThread
                            comment={reply}
                            currentUserId={currentUserId}
                            currentUser={currentUser}
                            depth={depth + 1}
                            repliesByParent={repliesByParent}
                            onReply={onReply}
                            onEdit={onEdit}
                            onDelete={onDelete}
                            onReactComment={onReactComment}
                            onLoadReplies={onLoadReplies}

                        />
                    ))}
                />
            ) : null}
        </>
    )

    return (
        // `IdentityContentRow` (composite) owns the avatar+byline+column shape — both
        // its seams are `tight` ON PURPOSE, a denser standalone treatment, NOT a
        // `src`-fidelity port (see the composite's own file header). `nested` draws the
        // reply indent guide via the `Stack` frame prop.
        <IdentityContentRow
            avatarSrc={comment.author.avatarUrl}
            avatarName={comment.author.username}
            avatarSeed={comment.author.id}
            avatarSize="sm"
            nested={depth > 0}


            byline={() => (
                <CommentByline
                    username={comment.author.username}
                    isFounderAuthor={comment.isFounderAuthor}
                    createdTimeAgo={comment.createdTimeAgo}
                    isEdited={comment.isEdited}
                />
            )}
            // `body` is the former `children` slot (COMPOSITE-8) — a component
            // reference, not a built node. `threadBody` (StackV wrapping
            // bodyAndActions + reply composer + replies subtree) is already
            // computed above per the current render's state, so the wrapper here
            // only needs to hand it back.
            body={() => (
                /* `grouped` — separates [body+actions, tight together] from whatever
                    comes after a reply composer/toggle/subtree: the seam right before
                    a reply composer appears needs more
                    room than the tight identity block above it (also where the
                    Facebook-style connector line will run). */
                <StackV gap={4} items={[() => threadBody]} />
            )}
        />
    )
}

