import { InputText } from "@/components/atoms/forms"
import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { PlayIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { ButtonRadioGroup } from "@/components/composites/buttons/ButtonRadioGroup"

import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Callout } from "@/components/composites/feedback/Callout"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `QuizSetup` — choose the shape of a drill (length, seniority, name), then
 * start it. The block owns the domain wording and the lengths behind it: the
 * learner picks "quick" or "deep" and the block turns that into 5 or 10 cards,
 * saying so on the button. A run already in progress takes priority — the resume
 * strip leads the card above the form. A failed draw is reported next to the
 * button that failed.
 */

/** How long a drill runs. */
export type QuizLength = "quick" | "deep"

/** Seniority the questions aim at. */
export type QuizLevel = "junior" | "middle" | "senior" | "staff"

/** Card count per length. The BLOCK owns this — it is the judgement, not a prop. */
const LENGTH_CARDS: Record<QuizLength, number> = { quick: 5, deep: 10 }

const LENGTH_LABEL: Record<QuizLength, string> = { quick: "Quick", deep: "Deep" }

const LEVEL_LABEL: Record<QuizLevel, string> = {
    junior: "Junior",
    middle: "Middle",
    senior: "Senior",
    staff: "Staff",
}

/** A run the learner left unfinished. */
export interface QuizResumable {
    /** What the run was called when it was started. */
    name: string
    /** How many cards were answered already. */
    answered: number
    /** How many cards the run has in total. */
    total: number
    /** Fired when the learner picks the run back up. */
    onResume: () => void
}

/** Props for {@link QuizSetup}. */
export interface QuizSetupProps {
    /** Section label, localized by the caller — e.g. "Set up session". */
    label: string
    /** Current run name. */
    name: string
    /** Fired as the learner types a name. */
    onNameChange: (value: string) => void
    /** Chosen length. */
    length: QuizLength
    /** Fired when the learner picks a length. */
    onLengthChange: (length: QuizLength) => void
    /** Chosen seniority. */
    level: QuizLevel
    /** Fired when the learner picks a seniority. */
    onLevelChange: (level: QuizLevel) => void
    /** Fired when the learner starts the run. */
    onStart: () => void
    /** A run left unfinished. Present → the resume strip leads the card. */
    resumable?: QuizResumable
    /** `true` → the draw is in flight; the start button owns the busy affordance. */
    isPending?: boolean
    /** Set → the draw failed. Reported beside the action that failed. */
    errorMessage?: string
    /** `true` → the card draws its own mirror while the setup data loads. */
    isSkeleton?: boolean
}

/**
 * The drill setup form. See the file header for the full contract.
 *
 * @param props - {@link QuizSetupProps}
 */
const QuizSetup = ({
    label,
    name,
    onNameChange,
    length,
    onLengthChange,
    level,
    onLevelChange,
    onStart,
    resumable,
    isPending = false,
    errorMessage,
    isSkeleton = false,
}: QuizSetupProps) => {
    const nameField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Session name" />,
                ({ isSkeleton }: SkeletonProps) => (
                    <InputText
                        value={name}
                        onValueChange={onNameChange}
                        placeholder="e.g. review Docker before the interview"
                        ariaLabel="Session name"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    const lengthField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Length" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Session length"
                        value={length}
                        onChange={onLengthChange}

                        items={(Object.keys(LENGTH_LABEL) as Array<QuizLength>).map((key) => ({
                            value: key,
                            content: `${LENGTH_LABEL[key]} · ${LENGTH_CARDS[key]} questions`,
                        }))}
                    />
                ),
            ]}
        />
    )

    const levelField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Level" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Question level"
                        value={level}
                        onChange={onLevelChange}

                        items={(Object.keys(LEVEL_LABEL) as Array<QuizLevel>).map((key) => ({
                            value: key,
                            content: LEVEL_LABEL[key],
                        }))}
                    />
                ),
            ]}
        />
    )

    const submitRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        label={`Start · ${LENGTH_CARDS[length]} questions`}
                        variant="primary"
                        prefixIcon={PlayIcon}
                        onPress={onStart}
                        isPending={isPending}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // The error sits WITH the action that failed. At the top of the card it
    // would read as a problem with the whole form.
    const actionField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ...(errorMessage != null ? [() => (
                    <Callout
                        status="danger"
                        title={errorMessage}

                    />
                )] : []),
                () => submitRow,
            ]}
        />
    )

    const formBody = (
        <>
            {resumable != null ? (
                // A learner who left mid-run almost always means to come back. Making
                // them scroll past a start button to find their own session is how one
                // run gets abandoned twice.
                <Callout
                    title={resumable.name}
                    description={`In progress · ${resumable.answered}/${resumable.total} questions`}
                    actionLabel="Continue"
                    onAction={resumable.onResume}

                />
            ) : null}

            {nameField}
            {lengthField}
            {levelField}
            {actionField}
        </>
    )

    return (
        <div>
            <SurfaceCard
                label={label}
                isSkeleton={isSkeleton}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => formBody]} />}
            />
        </div>
    )
}

export { QuizSetup }

import React, { useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Button as HeroButton, Popover as HeroPopover } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { ReactionPicker } from "@/components/atoms/feedback/ReactionPicker"
import { StackH } from "@/components/frames/Stack"
import { ReactionGlyph } from "./ReactionGlyph"
import { REACTION_BY_TYPE, type ReactionButtonProps, type ReactionType } from "./types"

export type { ReactionType, ReactionCount, ReactionButtonProps } from "./types"

/**
 * BLOCK — `ReactionButton`: the Facebook-style six-emotion reaction control —
 * pill trigger + Popover picker + compact summary. Shared verbatim between
 * `ContentReaction` (the lesson-level reaction) and each comment row in
 * `ContentDiscussion`'s thread — the SAME control real `src`'s `ReactionBar`
 * is, reused between `InteractionBar` and `CommentItem`.
 *
 * LEAF by STRUCTURE (§14d.2). Which emotion is picked and whether the
 * summary is empty keep the same two-part shape => states. The caller
 * flipping `isSkeleton` is its own leaf.
 */

/**
 * The reaction trigger + picker + summary. See the file header for the full contract.
 *
 * @param props - {@link ReactionButtonProps}
 */
const ReactionButton = ({
    myReaction = null,
    counts = [],
    onReact,
    isPending = false,
    isSkeleton = false,
}: ReactionButtonProps) => {
    // controlled so the popover closes as soon as an emotion is picked — mirrors real ReactionBar
    const [isOpen, setIsOpen] = useState(false)

    const total = counts.reduce((sum, entry) => sum + entry.count, 0)
    // busiest emotions first, top 3 — same cap real ReactionBar uses for the stacked summary
    const topReactions = counts
        .slice()
        .sort((prev, next) => next.count - prev.count)
        .slice(0, 3)
        .map((entry) => REACTION_BY_TYPE[entry.type])

    const onPick = (type: ReactionType) => {
        setIsOpen(false)
        onReact(myReaction === type ? null : type)
    }

    if (isSkeleton) {
        return <span className="inline-block h-8 w-28 animate-pulse rounded-full bg-default" />
    }

    // compact summary: stacked top emojis + total — dropped entirely at zero
    const summaryRow = total > 0 ? (
        <StackH
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            align="center"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <span className="flex items-center -space-x-1">
                        {topReactions.map((reaction) => (
                            <ReactionGlyph key={reaction.type} type={reaction.type} size="sm" />
                        ))}
                    </span>
                ),
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" text={String(total)} />,
            ]}
        />
    ) : null

    const triggerAndSummary = (
        <>
            {/* trigger: opens the 6-emotion picker; shows the viewer's own pick once set */}
            <HeroPopover isOpen={isOpen} onOpenChange={setIsOpen}>
                <HeroPopover.Trigger>
                    <HeroButton
                        variant="tertiary"
                        isDisabled={isPending}
                        className="rounded-full"

                    >
                        <ReactionGlyph type={myReaction ?? "like"} size="sm" />
                        <span className="text-sm">
                            {myReaction ? REACTION_BY_TYPE[myReaction].label : "React"}
                        </span>
                    </HeroButton>
                </HeroPopover.Trigger>
                {/* TODO(atom): heavy skin-shape (rounded-full + px-2 py-1 pill) — a frame cannot own it,
 wrap with a hand-set data-principle for now. `className` sits on `HeroPopover.Content`
 itself (the vendor's OWN rendered surface, react-aria `Popover`), not a raw <div>
 we author, so `Box` can't wrap it (moving the shape down onto an inner wrapping
 Box would leave the real popover surface with its default non-pill radius showing
 behind it — a visible shape regression). `data-principle` on `Content` directly is
 type-safe (forwarded through `DOMAttributes`), so tagged in place instead. Needs a
 dedicated pill-popover atom/composite to own this shape. Same declared shape
 as `QaReactionBar.tsx`'s trigger.
 inset-exception: pill geometry, the same px-2 py-1 HeroUI ships in chip.css. */}
                <HeroPopover.Content data-principle="pill-pad" className="overflow-visible rounded-full px-2 py-1">
                    <ReactionPicker
                        items={Object.values(REACTION_BY_TYPE).map((reaction) => ({ key: reaction.type, imgSrc: `/reactions/${reaction.type}.svg`, label: reaction.label }))}
                        activeKey={myReaction}
                        onSelect={(key) => onPick(key as ReactionType)}
                    />
                </HeroPopover.Content>
            </HeroPopover>

            {summaryRow}
        </>
    )

    return (
        <StackH gap={3} principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            align="center" isSkeleton={isSkeleton} items={[() => triggerAndSummary]}  />
    )
}

export { ReactionButton }

import React from "react"
import { WarningIcon } from "@phosphor-icons/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Callout } from "@/components/composites/feedback/Callout"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { SurfaceCardAccordion, type SurfaceCardAccordionItem } from "@/components/composites/cards/SurfaceCard"
import { ContentRelatedList, type ContentRelatedItem } from "@/components/blocks/learn/ContentRelatedList"
import { StackV } from "@/components/frames/Stack"

/**
 * `TaskBriefBody` — the reading column of a personal-project milestone task. A task
 * resolves into exactly one of two shapes depending on whether it carries a Schema
 * V2 brief: `SchemaV2Brief` (modern per-language markdown instructions) or
 * `LegacySchemaV1` (the older public criteria accordion + code guides). A task is
 * never both, so these are two leaves; `Skeleton` is a third (the block guesses
 * Schema V2 while loading). Within each schema shape, `isLocked` toggling the notice
 * is a plain data state.
 */

/** One pass criterion of a SCHEMA V1 (legacy) task — `src`'s `MilestoneTaskCriteriaEntity`. */
export interface TaskBriefCriteriaItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** Criterion trigger text. */
    text: string
    /** Grading hint, markdown. Blank → the row shows a plain "no hint yet" line instead. */
    hint?: string
    /** Points this criterion is worth — rides as a trailing chip on the trigger. */
    score: number
}

/** One per-language implementation guide of a SCHEMA V1 (legacy) task — `src`'s `CodeImplementationEntity`. */
export interface TaskBriefCodeImplementationItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** Language label (typescript / java / csharp / go). */
    lang: string
    /** Mapping guide, markdown. */
    guide: string
    /** Example code, markdown. */
    example: string
}

/** Props for {@link TaskBriefBody}. */
export interface TaskBriefBodyProps {
    /** Task title. */
    title: string
    /** Task description. Omitted when the task carries none. */
    description?: string
    /**
     * `true` → the learner is previewing a task ahead of their current progress:
     * the reading stays visible but a warning notice replaces the graded panel
     * (out of scope here) with a way back to the unlocked task.
     */
    isLocked: boolean
    /** Fired from the locked notice's "go to current task" button. */
    onGoToCurrentTask: () => void
    /**
     * SCHEMA V2 per-language brief, already resolved to the active locale by
     * the backend (`src`'s `TaskBrief`). Blank/absent ⇒ this is a SCHEMA V1
     * task and the legacy fallback below takes over instead.
     */
    briefBody?: string
    /** SCHEMA V1 fallback: public pass criteria. Read only when `briefBody` is blank. */
    legacyCriteria?: ReadonlyArray<TaskBriefCriteriaItem>
    /** SCHEMA V1 fallback: per-language implementation guides. Read only when `briefBody` is blank. */
    legacyCodeImplementations?: ReadonlyArray<TaskBriefCodeImplementationItem>
    /** Related lessons worth reading before this task. Empty → `ContentRelatedList` renders nothing. */
    relatedItems: Array<ContentRelatedItem>
    /** Section label for the related list, localized by the caller. */
    relatedLabel: string
    /** `true` → title/description and the brief-body guess switch to their own shimmer. */
    isSkeleton?: boolean
}

/** Fixed copy for the locked-preview notice — this block owns its own wording (§14d.1). */
const LOCKED_ALERT_TITLE = "Finish the previous task first"
const LOCKED_ALERT_DESCRIPTION = "You can still read this task's criteria. AI evaluation, feedback, history and the GitHub section unlock once you finish the previous step."
const LOCKED_ALERT_BUTTON_LABEL = "Back to current task"

/** Fixed copy for the SCHEMA V1 fallback card's two sub-labels. */
const CRITERIA_LABEL = "Grading criteria"
const CRITERIA_EMPTY_TITLE = "This task has no grading criteria yet."
const CRITERIA_NO_HINT = "No guidance for this criterion yet."
const IMPLEMENTATION_GUIDE_HEADING = "Guide"
const IMPLEMENTATION_EXAMPLE_HEADING = "Example"

/** `SurfaceCardAccordion.emptyState` for the SCHEMA V1 criteria fallback — a component reference (COMPOSITE-4), not a built element. */
const CriteriaEmptyState = () => <EmptyState title={CRITERIA_EMPTY_TITLE} />

/** How many shimmer paragraph lines `BriefMarkdown` guesses while `isSkeleton` — see file header. */
const BRIEF_SKELETON_LINE_WIDTHS = ["w-full", "w-full", "w-3/4", "w-2/3"] as const

/**
 * The personal-project task reading column. See the file header for the full
 * schema-generation contract and every judgement call.
 *
 * @param props - {@link TaskBriefBodyProps}
 */
const TaskBriefBody = ({
    title,
    description,
    isLocked,
    onGoToCurrentTask,
    briefBody,
    legacyCriteria,
    legacyCodeImplementations,
    relatedItems,
    relatedLabel,
    isSkeleton = false,
}: TaskBriefBodyProps) => {
    const trimmedBrief = briefBody?.trim() ?? ""
    // Schema-generation test, identical to `src`'s `(displayTask?.briefs?.length ?? 0) === 0`:
    // a brief present ⇒ SCHEMA V2, this task's rubric stays internal to the brief text.
    // While isSkeleton the generation isn't known yet — guessed SCHEMA V2, see file header.
    const showBrief = isSkeleton || trimmedBrief.length > 0
    const showLegacy = !isSkeleton && trimmedBrief.length === 0

    const criteriaItems: Array<SurfaceCardAccordionItem> = (legacyCriteria ?? []).map((item, index) => ({
        id: item.key,
        title: `${index + 1}. ${item.text}`,
        titleEnd: () => <Chip tone="accent" text={`${item.score} pts`} />,
        body: () => (
            item.hint?.trim() ? (
                <MarkdownContent source={item.hint} measure="compact" />
            ) : (
                <Typography size="sm" color="muted" isItalic text={CRITERIA_NO_HINT} />
            )
        ),
    }))

    const implementationBody = (item: TaskBriefCodeImplementationItem) => (
        <StackV
            gap={2}
            items={[
                () => <Typography size="xs" weight="semibold" color="muted" text={IMPLEMENTATION_GUIDE_HEADING} />,
                () => <MarkdownContent source={item.guide} measure="compact" />,
                () => <Typography size="xs" weight="semibold" color="muted" text={IMPLEMENTATION_EXAMPLE_HEADING} />,
                () => <MarkdownContent source={item.example} measure="compact" />,
            ]}
        />
    )

    const implementationItems: Array<SurfaceCardAccordionItem> = (legacyCodeImplementations ?? []).map((item) => ({
        id: item.key,
        title: item.lang,
        body: () => implementationBody(item),
    }))

    const readingColumn = (
        <>
            {/* TitleDesc — always present; both lines fall back to their own shimmer bar. */}
            <StackV
                gap={2}
                isSkeleton={isSkeleton}

                items={[
                    () => <Typography size="h3" weight="bold" isSkeleton={isSkeleton} classNames={isSkeleton ? ["w-1/2"] : undefined} text={title} />,
                    ...(isSkeleton
                        ? [() => <Typography size="sm" color="muted" isSkeleton classNames={["w-2/3"]} />]
                        : description != null && description.trim().length > 0
                            ? [() => <Typography size="sm" color="muted" text={description} />]
                            : []),
                ]}
            />

            {/* LockedAlert — self-hides when unlocked; honored regardless of `isSkeleton` since
                `isLocked` is already-resolved data the caller holds, same call as
                `ContentArticle`'s own `isLocked`. */}
            {isLocked ? (
                <Callout
                    status="warning"
                    icon={WarningIcon}
                    title={LOCKED_ALERT_TITLE}
                    description={LOCKED_ALERT_DESCRIPTION}
                    actionLabel={LOCKED_ALERT_BUTTON_LABEL}
                    onAction={onGoToCurrentTask}

                />
            ) : null}

            {/* BriefMarkdown — SCHEMA V2. Skeleton guesses a plain shimmer paragraph rather
                than calling `MarkdownContent` with no source, mirroring `ChallengeBrief`'s
                own list-skeleton judgement call (a viewer needs a real payload; a guessed
                loading state cannot fabricate one). */}
            {showBrief ? (
                isSkeleton ? (
                    <StackV
                        gap={2}
                        isSkeleton={isSkeleton}

                        items={BRIEF_SKELETON_LINE_WIDTHS.map((width) => () => (
                            <Typography size="base" isSkeleton classNames={[width]} />
                        ))}
                    />
                ) : (
                    <MarkdownContent source={trimmedBrief} measure="reading" />
                )
            ) : null}

            {/* LegacyCriteriaCard — SCHEMA V1 fallback ONLY, never while isSkeleton (see file header). */}
            {showLegacy ? (
                <StackV
                    gap={4}
                    isSkeleton={isSkeleton}

                    items={[
                        () => <Typography size="sm" weight="semibold" text={CRITERIA_LABEL} />,
                        () => (
                            <SurfaceCardAccordion
                                items={criteriaItems}
                                allowsMultipleExpanded
                                emptyState={CriteriaEmptyState}


                            />
                        ),
                        ...(implementationItems.length > 0 ? [() => (
                            <SurfaceCardAccordion
                                items={implementationItems}
                                allowsMultipleExpanded


                            />
                        )] : []),
                    ]}
                />
            ) : null}

            {/* RelatedList — the block never gates it; `ContentRelatedList` already self-hides. */}
            <ContentRelatedList
                items={relatedItems}
                label={relatedLabel}
                isSkeleton={isSkeleton}


            />
        </>
    )

    return (
        <StackV identity={{ tier: "block", component: "TaskBriefBody" }} gap={6} isSkeleton={isSkeleton} items={[() => readingColumn]} />
    )
}

export { TaskBriefBody }

"use client"

import React, { createContext, useContext, useEffect, useState } from "react"
import type { ReactNode } from "react"
import { motion, AnimatePresence, useReducedMotion } from "framer-motion"
import { cn } from "@heroui/react"
import { SidebarSimpleIcon } from "@phosphor-icons/react"
import { ButtonBase } from "@/components/atoms/buttons/Button/ButtonBase"
import { Typography } from "@/components/atoms/text/Typography"
import { DragScrollArea } from "@/components/behaviors/DragScrollArea"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `CollapsibleSidebar` — a content-agnostic shell for a left navigation sidebar
 * that collapses in place (no overlay/Drawer). Owns collapse/expand, the width
 * animation, persisting the choice to `localStorage`, and a `useSidebarCollapsed`
 * context so nav-row content can self-adapt to the icon-only rail. It never
 * inspects `children`. One leaf: `topSlot` presence and the collapsed flag are
 * data, so they are states, not separate leaves.
 */

/** Expanded panel width (full nav). */
const EXPANDED_WIDTH = "16rem"
/** Collapsed rail width — fits a centered icon row + the toggle. */
const COLLAPSED_WIDTH = "4rem"

/**
 * Named transition shapes (not inline object literals at the call site — check-inline-types
 * gate) for the width animation: a spring when motion is welcome, instant when the reader (or
 * their OS) asked for reduced motion.
 */
const SPRING_TRANSITION = { type: "spring" as const, stiffness: 420, damping: 38 }
const INSTANT_TRANSITION = { duration: 0 }
/** Title fade — quick cross-fade, same instant fallback under reduced motion. */
const FADE_TRANSITION = { duration: 0.15 }

/**
 * Collapsed flag shared with nav-row children so a row can drop to icon-only in
 * the rail. Internal UI chrome state — not an app store.
 */
const SidebarCollapsedContext = createContext(false)

/** Read whether the surrounding {@link CollapsibleSidebar} is collapsed (icon-rail). */
export const useSidebarCollapsed = (): boolean => useContext(SidebarCollapsedContext)

/** Props for the {@link CollapsibleSidebar} composite. */
export interface CollapsibleSidebarProps {
    /** Heading shown in the panel header (hidden while collapsed). */
    title: string
    /** Accessible label for the collapse toggle (expanded state). */
    collapseLabel: string
    /** Accessible label for the expand toggle (collapsed state). */
    expandLabel: string
    /**
     * Stable key under which the collapsed flag persists in `localStorage`, so
     * the choice survives navigation between pages that share this sidebar.
     */
    storageKey: string
    /**
     * Optional node pinned BETWEEN the header and the scrollable nav — always
     * visible (outside the scroll area). Rendered inside the collapsed-context
     * provider, so it can adapt to the rail (e.g. a resume pill → play icon).
     */
    topSlot?: ReactNode
    /** The panel body — nav rows/groups; content-agnostic, this shell never inspects them. */
    children: ReactNode
    className?: string
}

/**
 * A left navigation sidebar that collapses IN PLACE: the panel animates between
 * a full {@link EXPANDED_WIDTH} (title + nav) and a thin {@link COLLAPSED_WIDTH}
 * rail (just the toggle), and the surrounding content reflows beside it — no
 * overlay/Drawer. Self-contained: the collapsed state is local UI chrome,
 * hydrated from storage on mount (SSR-safe — starts expanded, then syncs).
 *
 * @param props - {@link CollapsibleSidebarProps}
 */
export const CollapsibleSidebar = ({
    title,
    collapseLabel,
    expandLabel,
    storageKey,
    topSlot,
    children,
    className,
}: CollapsibleSidebarProps) => {
    const reduceMotion = useReducedMotion()
    const [collapsed, setCollapsed] = useState(false)

    // hydrate the persisted choice after mount (avoids SSR/client mismatch)
    useEffect(() => {
        const stored = window.localStorage.getItem(storageKey)
        if (stored !== null) {
            setCollapsed(stored === "true")
        }
    }, [storageKey])

    /** Flip + persist the collapsed flag. */
    const toggle = () => {
        setCollapsed((prev) => {
            const next = !prev
            window.localStorage.setItem(storageKey, String(next))
            return next
        })
    }

    // header: toggle always present; title fades out while collapsed
    const headerRow = (
        <>
            <AnimatePresence initial={false}>
                {!collapsed ? (
                    <motion.div
                        key="title"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        transition={reduceMotion ? INSTANT_TRANSITION : FADE_TRANSITION}
                        className="min-w-0"
                    >
                        <Typography
                            size="h5"
                            weight="bold"
                            truncate
                            text={title}

                        />
                    </motion.div>
                ) : null}
            </AnimatePresence>
            <ButtonBase
                isIconOnly
                variant="ghost"
                size="sm"
                ariaLabel={collapsed ? expandLabel : collapseLabel}
                prefixIcon={SidebarSimpleIcon}
                onPress={toggle}

            />
        </>
    )

    // §10a: the vertical rhythm between header / topSlot / nav is owned by THIS
    // StackV's gap — no section carries its own margin (a prior draft put
    // `mb-6` on the header row itself, flagged by check-padding as a second
    // owner for the same seam).
    const panel = (
        <>
            <StackH gap={3} principle="flex-action" justify={collapsed ? "center" : "between"} items={[() => headerRow]}
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            />

            {/* pinned top slot (e.g. resume pill) — above the scroll area, always
                visible. min-w-0: a column-flex item defaults to content-width
                (min-width: auto), which would let it overflow the rail and get
                hard-clipped by overflow-hidden instead of shrinking so its own
                `truncate` text can ellipsize. */}
            <div className="min-w-0">
                {topSlot}
            </div>

            {/* body: the nav — ALWAYS rendered; row content decides its own icon-only
                look off `useSidebarCollapsed`. `DragScrollArea` owns the overflow
                (hidden scrollbar + Windows-safe pointer-pan); `StackV` gives the
                column its `gap={4}` rhythm and default `align="stretch"` (rows
                fill the rail's width whether expanded or collapsed), since the scroll
                frame itself lays out nothing. */}
            <nav
                className="flex min-h-0 flex-1 flex-col"

            >
                <DragScrollArea size={40} className="flex-1">
                    <StackV gap={4} items={[() => children]} />
                </DragScrollArea>
            </nav>
        </>
    )

    return (
        <SidebarCollapsedContext.Provider value={collapsed}>
            <motion.aside

                initial={false}
                animate={{ width: collapsed ? COLLAPSED_WIDTH : EXPANDED_WIDTH }}
                transition={reduceMotion ? INSTANT_TRANSITION : SPRING_TRANSITION}
                className={cn(
                    // ONE padding wrapper for the whole rail: p-6 expanded / px-3 py-6
                    // collapsed. No frame in this tree types an asymmetric inset, so this
                    // stays hand-written on the composite's own bespoke root (§13c precedent:
                    // Toolbar/ModalShell/DrawerShell do the same on theirs).
                    "flex h-full shrink-0 overflow-hidden border-r border-default",
                    collapsed ? "px-3 py-6" : "p-6",
                    className,
                )}
            >
                <StackV gap={6} classNames={["min-h-0", "flex-1"]} items={[() => panel]} />
            </motion.aside>
        </SidebarCollapsedContext.Provider>
    )
}

import React from "react"
import { Link as HeroUILink } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import type { FooterLinkItem } from ".."

/** Props for {@link FooterLinkColumn}. */
export interface FooterLinkColumnProps {
    title: string
    links: Array<FooterLinkItem>
}

/**
 * One titled column of link rows. Internal helper, not its own anatomy node
 * (same convention `Navbar`'s internal `NavbarLanguageMenu`/`NavbarThemeSwitch`
 * use) — its own `StackV`/`Typography`/`Link` parts are tagged directly.
 */
export const FooterLinkColumn = ({ title, links }: FooterLinkColumnProps) => {
    const rows = links.map((link) => (
        <HeroUILink
            key={link.id}
            onPress={link.onPress}
            className="w-fit cursor-pointer text-sm text-muted transition-colors hover:text-foreground"

        >
            {link.label}
        </HeroUILink>
    ))

    const column = (
        <>
            <Typography size="sm" weight="bold" text={title} />
            <StackV gap={2} items={[() => rows]} />
        </>
    )

    return <StackV identity={{ tier: "block", component: "FooterLinkColumn" }} gap={4} items={[() => column]} />
}

import React from "react"
import { Link as HeroUILink, cn } from "@heroui/react"
import { FaFacebook, FaGithub, FaLinkedin } from "react-icons/fa6"
import { Logo } from "@/components/atoms/display/Logo"
import { Typography } from "@/components/atoms/text/Typography"
import type { IconComponent } from "@/components/atoms/buttons/Button"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { FooterLinkColumn } from "./FooterLinkColumn"

/**
 * BLOCK — `Footer`: the marketing site footer. See the component's own file
 * header for the full port/reuse ledger; this story only exercises what a
 * caller actually configures.
 *
 * ONE LEAF — the footer has a single structural shape (brand column, two link
 * columns, bottom bar); nothing about its composition ever drops or gains a
 * whole node. Longer vs. shorter link lists are DATA, so they live as states
 * inside this one leaf rather than separate leaves.
 */

/** One row inside a footer link column, or one of the two bottom-bar legal links. */
export interface FooterLinkItem {
    /** Stable id — also the React key. */
    id: string
    /** Visible label, already localized by the caller. */
    label: string
    /** Fired when the row is pressed — navigation is the caller's job. */
    onPress: () => void
}

/** One founder social icon link. */
export interface FooterSocialLink {
    /** Stable id — also the React key. */
    id: string
    /** Aria-label for the glyph-only trigger, e.g. "GitHub". */
    label: string
    /** Brand glyph component (a `react-icons/fa6` icon — see file header). */
    icon: IconComponent
    /** Fired when the icon is pressed — opening the external URL is the caller's job. */
    onPress: () => void
}

/** Props for {@link Footer}. */
export interface FooterProps {
    /** The "Explore" column's rows (courses/blog/talents/jobs/community in the real app). */
    exploreLinks: Array<FooterLinkItem>
    /** The "Support" column's rows (contact/email in the real app). */
    supportLinks: Array<FooterLinkItem>
    /** Founder social links (Facebook/LinkedIn/GitHub in the real app). */
    socials: Array<FooterSocialLink>
    /** Fired when the bottom-bar "Terms" stub is pressed. */
    onTermsPress: () => void
    /** Fired when the bottom-bar "Privacy" stub is pressed. */
    onPrivacyPress: () => void
    /** Extra class on the root `<footer>` (placement only). */
    className?: string
}

/**
 * The marketing site footer. See the file header for the static-vs-prop copy
 * split and the BrandLockup/icon-rule judgement calls.
 *
 * @param props - {@link FooterProps}
 */
const Footer = ({
    exploreLinks,
    supportLinks,
    socials,
    onTermsPress,
    onPrivacyPress,
    className,
}: FooterProps) => {
    const year = new Date().getFullYear()

    const wordmark = (
        <>
            <div className="text-sm font-semibold leading-none text-foreground">StarCi</div>
            <div className="text-[8px] uppercase leading-none text-muted">Academy</div>
        </>
    )

    // brand mark + wordmark, inlined (see file header: BrandLockup not
    // promoted). `StackH`/`StackV` (not a hand-rolled flex span) per §13z —
    // spacing is words. `Logo` itself stays unbadged here, same as `Navbar`'s
    // own brand-mark span (not in either block's ANNOTATE map).
    const brandMark = (
        <>
            <Logo size="footer" />
            <div className="hidden @app-md:flex">
                <StackV gap={1} items={[() => wordmark]} />
            </div>
        </>
    )

    const socialLinks = socials.map((social) => {
        const Icon = social.icon
        return (
            <HeroUILink
                key={social.id}
                onPress={social.onPress}
                aria-label={social.label}
                className="text-muted transition-colors hover:text-foreground"

            >
                <Icon className="size-5" aria-hidden />
            </HeroUILink>
        )
    })

    const brandColumn = (
        <>
            <StackH gap={1} classNames={["w-fit", "self-start"]} items={[() => brandMark]} />
            <Typography
                size="sm"
                color="muted"
                text="Learn by building real systems with your own hands — ready for any technical interview."

            />
            <StackH gap={3} items={[() => socialLinks]} />
        </>
    )

    const linkColumns = (
        <>
            <FooterLinkColumn title="Explore" links={exploreLinks} />
            <FooterLinkColumn title="Support" links={supportLinks} />
        </>
    )

    // top region: brand + tagline + socials (left) · two link columns (right)
    const topRegion = (
        <>
            <div className="max-w-sm">
                <StackV gap={4} items={[() => brandColumn]} />
            </div>
            <StackH gap={7} principle="layout-split"
                explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                at="sm" items={[() => linkColumns]}  />
        </>
    )

    const legalLinks = (
        <>
            <HeroUILink
                onPress={onTermsPress}
                className="cursor-pointer text-xs text-muted transition-colors hover:text-foreground"

            >
                Terms
            </HeroUILink>
            <HeroUILink
                onPress={onPrivacyPress}
                className="cursor-pointer text-xs text-muted transition-colors hover:text-foreground"

            >
                Privacy
            </HeroUILink>
        </>
    )

    // bottom bar: copyright + credit (left) · legal stubs (right)
    const bottomBar = (
        <>
            <Typography
                size="xs"
                color="muted"
                text={`(c) ${year} StarCi Academy - Built by Nguyen Van Tu Cuong`} // vn-ok: the author's real name

            />
            <StackH gap={3} items={[() => legalLinks]} />
        </>
    )

    const sections = (
        <>
            <StackH
                gap={7}
                principle="layout-split"
                explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                justify="between"
                at="md"

                items={[() => topRegion]}
            />
            <div className="items-start @app-sm:items-center">
                <StackH
                    gap={3}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    justify="between"
                    at="sm"

                    items={[() => bottomBar]}
                />
            </div>
        </>
    )

    const footerBody = (
        <StackV gap={6} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            divider items={[() => sections]}  />
    )

    return (
        <footer className={cn("border-t border-default bg-surface", className)}>
            <Container size="xl" padding={6} body={() => footerBody} />
        </footer>
    )
}

export { Footer }

/** Re-exported so `FaFacebook`/`FaLinkedin`/`FaGithub` fixtures stay ONE source for stories. */
export { FaFacebook, FaGithub, FaLinkedin }

import React, { useEffect, useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import {
    cn,
    Button as HeroButton,
    Dropdown,
    Kbd,
    Label,
    Popover,
    PopoverContent,
} from "@heroui/react"
import {
    BellIcon,
    ChecksIcon,
    CircleIcon,
    MagnifyingGlassIcon,
    ShoppingCartIcon,
    SidebarSimpleIcon,
    UserIcon,
} from "@phosphor-icons/react"
import { NavbarLanguageMenu } from "./NavbarLanguageMenu"
import { NavbarThemeSwitch } from "./NavbarThemeSwitch"
import type { NavbarLanguageOption } from "./types"
import { Logo } from "@/components/atoms/display/Logo"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Badge } from "@/components/atoms/display/Badge"
import { Divider } from "@/components/atoms/display/Divider"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Typography } from "@/components/atoms/text/Typography"
import { Button, type IconComponent } from "@/components/atoms/buttons/Button"
import { ButtonRadioGroup } from "@/components/composites/buttons/ButtonRadioGroup"
import { InputButtonLike } from "@/components/composites/buttons/InputButtonLike"
import { AsyncContent } from "@/components/composites/async/AsyncContent"
import { ListRow } from "@/components/composites/lists/List"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `Navbar` — the sticky top app bar. Two structural leaves: the desktop row
 * (route pills + inline language/theme) and the mobile collapsed row (icon bar
 * + drawer trigger) are different compositions. Signed-in vs guest, empty vs
 * busy badges, and drawer open vs closed are data, so they are states inside
 * the matching leaf. Both leaves render the same component (the `@app-md:`
 * rules live in its className), so the mobile leaf pins a narrow
 * `renderClassName` frame to force the collapsed row into view.
 */

/** One top-level desktop/mobile route entry. */
export interface NavLinkItem {
    /** Stable id — also the value reported to the desktop pill group. */
    id: string
    /** Visible label, already localized by the caller. */
    label: string
    /** Whether this entry matches the current route. */
    isActive?: boolean
    /** Fired when the entry is picked (desktop pill or mobile drawer row). */
    onPress: () => void
}

export type { NavbarLanguageOption }

/** One row in the notification popover's list. */
export interface NavbarNotificationItem {
    /** Stable id. */
    id: string
    /** Primary line, already resolved/translated by the caller. */
    title: string
    /** Optional secondary line. */
    subtitle?: string
    /** Already-formatted relative time (e.g. "3 hours ago") — locale math is app wiring. */
    timeLabel: string
    /** `false` renders the unread dot leading the row. */
    isRead: boolean
}

/** Notification bell data + the callbacks its popover fires. */
export interface NavbarNotificationsData {
    /** Drives the bell's count badge; `0` hides it. */
    unreadCount: number
    /** Most-recent page, newest first. */
    items: Array<NavbarNotificationItem>
    /** `true` while the FIRST page is loading (no cache yet). */
    isLoading: boolean
    /** Already-translated error message; `null`/absent → no error branch. */
    error?: string | null
    /** Fired when a row is pressed (mark-read + navigate is the caller's job). */
    onItemPress: (item: NavbarNotificationItem) => void
    /** Fired by the header's bulk action. */
    onMarkAllRead: () => void
    /** Fired by the footer's deep-link action. */
    onSeeAll: () => void
    /** Fired by the error branch's retry button. */
    onRetry: () => void
}

/** The signed-in viewer, as far as the account menu's header row needs to know. */
export interface NavbarAccountUser {
    /** Drives the avatar fallback + the header row's primary line. */
    username: string
    /** Shown as the header row's secondary `@handle` line. */
    email?: string
    /** Uploaded avatar URL; `Avatar`'s own fallback chain covers the rest. */
    avatarUrl?: string | null
}

/** One row of the account dropdown's action list — covers BOTH the guest rows
 * (sign in / sign up) and the authed rows (dashboard / profile / sign out); the
 * caller decides which set to hand in via {@link NavbarAccountData.isAuthed}. */
export interface NavbarAccountMenuItem {
    /** Stable id. */
    id: string
    /** Visible label, already localized. */
    label: string
    /** Leading glyph, atom-scale (`size-5`) as this block owns the icon column. */
    icon?: IconComponent
    /** `true` → renders in the destructive tone (e.g. "Sign out"). */
    isDanger?: boolean
    /** Fired when the row is pressed. */
    onPress: () => void
}

/** Account menu data + the one state flag its header/list branch on. */
export interface NavbarAccountData {
    /** `true` → header shows {@link NavbarAccountData.user}; `false` → the guest prompt. */
    isAuthed: boolean
    /** Present only when {@link NavbarAccountData.isAuthed}. */
    user?: NavbarAccountUser
    /** `true` while the shared "who am I" query has not resolved yet. */
    isLoading: boolean
    /** The action rows below the header (see {@link NavbarAccountMenuItem}). */
    menuItems: Array<NavbarAccountMenuItem>
}

/** Props for {@link Navbar}. */
export interface NavbarProps {
    /** Fired when the brand mark is pressed — routing "home" is the caller's call. */
    onLogoPress: () => void
    /** Route entries — the ONE source both the desktop pills and the mobile drawer read. */
    navItems: Array<NavLinkItem>

    /** Placeholder text for the desktop search field; doubles as the mobile icon's aria-label. */
    searchPlaceholder: string
    /** Already-formatted shortcut hint (e.g. `"Ctrl K"`, `"⌘K"`) — OS detection is app wiring. */
    shortcutLabel: string
    /** Fired when the search trigger (field or icon) is pressed, or Ctrl/Cmd+K is hit. */
    onSearchPress: () => void

    /** Selectable locales. */
    languages: Array<NavbarLanguageOption>
    /** Currently active locale — must match one entry's `code`. */
    activeLocale: string
    /** Fired with the newly picked locale code. */
    onLocaleChange: (code: string) => void

    /** Dark-mode on/off (controlled). */
    isDarkMode: boolean
    /** Fired with the new on/off state. */
    onThemeToggle: (isDark: boolean) => void

    /** Items currently in the cart; `0` hides the count badge. */
    cartCount: number
    /** Fired when the cart icon is pressed. */
    onCartPress: () => void

    /** Notification bell data + callbacks. */
    notifications: NavbarNotificationsData
    /** Account menu data + callbacks. */
    account: NavbarAccountData

    /** Whether the mobile navigation drawer is open. Controlled by the caller. */
    isMobileDrawerOpen: boolean
    /** Fired on backdrop click / Escape / the close button / a row navigating away. */
    onMobileDrawerOpenChange: (isOpen: boolean) => void

    /** Extra class on the root `<nav>` (placement only). */
    className?: string
}

/** Props for {@link ShortcutHint}. */
interface ShortcutHintProps {
    shortcutLabel: string
}

const ShortcutHint = ({ shortcutLabel }: ShortcutHintProps) => (
    <Kbd><Kbd.Content>{shortcutLabel}</Kbd.Content></Kbd>
)

/**
 * The sticky top app bar. See the file header for the full reuse ledger and the
 * judgement calls this port makes.
 *
 * @param props - {@link NavbarProps}
 */
const Navbar = ({
    onLogoPress,
    navItems,
    searchPlaceholder,
    shortcutLabel,
    onSearchPress,
    languages,
    activeLocale,
    onLocaleChange,
    isDarkMode,
    onThemeToggle,
    cartCount,
    onCartPress,
    notifications,
    account,
    isMobileDrawerOpen,
    onMobileDrawerOpenChange,
    className,
}: NavbarProps) => {
    const [isNotificationsOpen, setNotificationsOpen] = useState(false)
    const [isAccountOpen, setAccountOpen] = useState(false)

    // Ctrl/Cmd+K — carried over from the real component (see file header): it only
    // ever calls a prop this block already owns, so it is not new app wiring.
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            const isK = event.key?.toLowerCase() === "k"
            if (!isK || !(event.ctrlKey || event.metaKey)) return
            event.preventDefault()
            onSearchPress()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [onSearchPress])

    const activeNavId = navItems.find((item) => item.isActive)?.id ?? ""

    // desktop-only route pills; the mobile drawer renders the same `navItems` as full rows.
    // `hidden @app-md:flex` is the WRAPPER's call (showing/hiding at a breakpoint is the
    // surrounding frame's decision, not the atom's — ATOM-5), so it sits on this span,
    // not on `ButtonRadioGroup`'s own `className`.
    const logoAndNavPills = (
        <>
            <span
                role="button"
                tabIndex={0}
                aria-label="StarCi Academy"
                onClick={onLogoPress}
                onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") onLogoPress()
                }}
                className="inline-flex cursor-pointer items-center"
            >
                <Logo />
            </span>
            <span className="hidden @app-md:flex">
                <ButtonRadioGroup
                    items={navItems.map((item) => ({
                        value: item.id,
                        content: <Typography size="sm" text={item.label} />,
                    }))}
                    value={activeNavId}
                    onChange={(id) => navItems.find((item) => item.id === id)?.onPress()}
                    ariaLabel="Main navigation"
                />
            </span>
        </>
    )

    // desktop: language + theme inline; the mobile drawer carries them instead
    const quickControls = (
        <>
            <NavbarLanguageMenu
                languages={languages}
                activeLocale={activeLocale}
                onLocaleChange={onLocaleChange}

            />
            <NavbarThemeSwitch isDarkMode={isDarkMode} onThemeToggle={onThemeToggle} />
        </>
    )

    const notificationSkeletonRows = [0, 1, 2].map((row) => (
        <ListRow key={row} title="" isSkeleton />
    ))

    const notificationRows = notifications.items.map((item, index) => (
        <ListRow
            key={item.id}
            leading={!item.isRead ? (
                ({ isSkeleton }: SkeletonProps) =>
                    isSkeleton ? null : <CircleIcon weight="fill" aria-hidden focusable="false" className="size-2 text-accent-soft-foreground" />
            ) : undefined}
            title={item.title}
            subtitle={item.subtitle}
            meta={() => <Typography size="xs" color="muted" text={item.timeLabel} />}
            onPress={() => notifications.onItemPress(item)}
            divider={index < notifications.items.length - 1}

        />
    ))

    const notificationHeader = (
        <>
            <Typography size="sm" weight="bold" text="Notifications" />
            {notifications.unreadCount > 0 ? (
                <Button
                    isIconOnly
                    variant="ghost"
                    size="sm"
                    prefixIcon={ChecksIcon}
                    ariaLabel="Mark all as read"
                    onPress={notifications.onMarkAllRead}

                />
            ) : null}
        </>
    )

    // notification popover body: header row → async list → footer link
    const notificationPanel = (
        <>
            <StackH gap={3} principle="sibling-stack" justify="between" items={[() => notificationHeader]}
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            />
            <AsyncContent
                isLoading={notifications.isLoading && notifications.items.length === 0}
                skeleton={() => <StackV gap={1} items={[() => notificationSkeletonRows]} />}
                isEmpty={notifications.items.length === 0}
                emptyContent={{ title: "No notifications yet" }}
                error={notifications.error}
                errorContent={{
                    title: notifications.error ?? "",
                    onRetry: notifications.onRetry,
                    retryLabel: "Try again",
                }}
                content={() => (
                    <div className="max-h-[420px] overflow-y-auto">
                        <StackV gap={1} items={[() => notificationRows]} />
                    </div>
                )}
            />
            <Button
                variant="ghost"
                size="sm"
                classNames={["w-full"]}
                label="See all"
                onPress={notifications.onSeeAll}

            />
        </>
    )

    const guestAccountRow = (
        <>
            <Avatar icon={UserIcon} fallback="icon" />
            <Typography size="sm" color="muted" text="Sign in to save your learning progress" />
        </>
    )

    const accountMenuHeader = (
        <AsyncContent
            isLoading={account.isLoading}
            skeleton={() => <UserCell username="" isSkeleton />}
            content={() => (account.isAuthed && account.user ? (
                <UserCell
                    username={account.user.username}
                    avatar={account.user.avatarUrl}
                    handle={account.user.email}
                />
            ) : (
                <StackH gap={3} items={[() => guestAccountRow]} />
            ))}
        />
    )

    // actions cluster: search · language/theme · cart · notifications · account · mobile menu
    const barActions = (
        <>
            {/* desktop: full input-style search field; mobile: icon only */}
            <span className="hidden w-[260px] @app-md:flex">
                <InputButtonLike
                    placeholder={searchPlaceholder}
                    icon={MagnifyingGlassIcon}
                    suffix={() => <ShortcutHint shortcutLabel={shortcutLabel} />}
                    onPress={onSearchPress}
                />
            </span>
            {/* `@app-md:hidden` moved off the atom onto this wrapper — a breakpoint
                show/hide is the surrounding frame's decision, not the atom's (ATOM-5). */}
            <span className="@app-md:hidden">
                <Button
                    isIconOnly
                    variant="ghost"
                    prefixIcon={MagnifyingGlassIcon}
                    ariaLabel={searchPlaceholder}
                    onPress={onSearchPress}

                />
            </span>

            <div className="hidden @app-md:flex">
                <StackH gap={3} items={[() => quickControls]} />
            </div>

            {/* cart — always shown (guests included), count badge only when non-empty.
                Raw HeroUI `Button` (not our atom, see file header): the atom's
                `isIconOnly` mode takes a single bare `prefixIcon` COMPONENT, with no
                room for the `Badge` this trigger anchors around its glyph. */}
            <HeroButton
                isIconOnly
                variant="tertiary"
                className="rounded-full"
                aria-label="Cart"
                onPress={onCartPress}

            >
                <Badge color="accent" count={cartCount}>
                    <ShoppingCartIcon className="size-5" />
                </Badge>
            </HeroButton>

            {/* notification bell — only meaningful for a signed-in viewer (carried over
                from the real component's own `if (!authenticated) return null`). Raw
                HeroUI Popover + Button (see file header: same badge-around-glyph gap as
                the cart trigger above). */}
            {account.isAuthed ? (
                <Popover isOpen={isNotificationsOpen} onOpenChange={setNotificationsOpen}>
                    <HeroButton
                        isIconOnly
                        variant="tertiary"
                        className="rounded-full"
                        aria-label="Notifications"

                    >
                        <Badge color="danger" count={notifications.unreadCount}>
                            <BellIcon className="size-5" />
                        </Badge>
                    </HeroButton>
                    <PopoverContent placement="bottom right" className="w-[360px]">
                        {/* inset-exception: vendor popover body padding, wider than tall, not a surface inset */}
                        <StackV gap={2} principle="control-pad" padding={{ x: 3, y: 2 }} items={[() => notificationPanel]}
                            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row."
                        />
                    </PopoverContent>
                </Popover>
            ) : null}

            {/* account menu — raw HeroUI Dropdown + Button (see file header): the
                authed trigger swaps its glyph for an `Avatar`, another shape the
                atom's bare-`IconComponent` slot cannot host. */}
            <Dropdown isOpen={isAccountOpen} onOpenChange={setAccountOpen}>
                <HeroButton
                    isIconOnly
                    variant="tertiary"
                    className="rounded-full"
                    aria-label="Account"

                >
                    {account.isAuthed ? (
                        <Avatar
                            size="sm"
                            name={account.user?.username}
                            src={account.user?.avatarUrl ?? undefined}
                            seed={account.user?.email ?? account.user?.username}
                        />
                    ) : (
                        <UserIcon className="size-5" />
                    )}
                </HeroButton>
                <Dropdown.Popover placement="bottom right" className="w-[300px]">
                    <StackV gap={1} padding={4} principle="cell-pad" body={() => accountMenuHeader}
                        explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                    />
                    <Divider />
                    <Dropdown.Menu aria-label="Account">
                        <Dropdown.Section>
                            {account.menuItems.map((item) => {
                                const Icon = item.icon
                                return (
                                    <Dropdown.Item
                                        key={item.id}
                                        id={item.id}
                                        textValue={item.label}
                                        className={item.isDanger ? "text-danger-soft-foreground" : undefined}
                                        onPress={item.onPress}

                                    >
                                        {Icon ? <Icon className="size-5" /> : null}
                                        <Label className={item.isDanger ? "text-danger-soft-foreground" : undefined}>{item.label}</Label>
                                    </Dropdown.Item>
                                )
                            })}
                        </Dropdown.Section>
                    </Dropdown.Menu>
                </Dropdown.Popover>
            </Dropdown>

            {/* mobile: expand icon → the navigation drawer. `@app-md:hidden` moved off the
                atom onto this wrapper (ATOM-5 — breakpoint visibility is the frame's call). */}
            <span className="@app-md:hidden">
                <Button
                    isIconOnly
                    variant="ghost"
                    prefixIcon={SidebarSimpleIcon}
                    ariaLabel="Open mobile menu"
                    onPress={() => onMobileDrawerOpenChange(true)}

                />
            </span>
        </>
    )

    // primary row — fixed 4rem tall, matching the real bar's height contract
    const primaryRow = (
        <>
            <StackH gap={6} items={[() => logoAndNavPills]} />
            <StackH gap={3} items={[() => barActions]} />
        </>
    )

    const mobileNavRows = navItems.map((item) => (
        <Button
            key={item.id}
            variant={item.isActive ? "secondary" : "ghost"}
            align="start"
            classNames={["w-full"]}
            label={item.label}
            onPress={() => {
                item.onPress()
                onMobileDrawerOpenChange(false)
            }}

        />
    ))

    const languageRow = (
        <>
            <Typography size="sm" text="Language" />
            <NavbarLanguageMenu
                languages={languages}
                activeLocale={activeLocale}
                onLocaleChange={onLocaleChange}

            />
        </>
    )

    const themeRow = (
        <>
            <Typography size="sm" text="Theme" />
            <NavbarThemeSwitch isDarkMode={isDarkMode} onThemeToggle={onThemeToggle} />
        </>
    )

    // controls hidden from the mobile bar live here: language + theme
    const drawerControls = (
        <>
            <StackH gap={3} principle="sibling-stack" justify="between" items={[() => languageRow]}
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            />
            <StackH gap={3} principle="sibling-stack" justify="between" items={[() => themeRow]}
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            />
        </>
    )

    const drawerNav = (
        <>
            <StackV gap={2} items={[() => mobileNavRows]} />
            <Divider />
            <StackV gap={4} items={[() => drawerControls]} />
        </>
    )

    return (
        <nav

            className={cn("sticky top-0 z-50 border-b border-default bg-surface", className)}
        >
            {/* primary row — fixed 4rem tall, matching the real bar's height contract */}
            <div className="h-16 min-h-16">
                <StackH
                    gap={6}
                    principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    justify="between"
                    padding={{ x: 4 }}

                    items={[() => primaryRow]}
                />
            </div>

            {/* mobile navigation drawer — the ONE local (non-overlay-store) drawer this run's
                contract calls for; every other overlay in this system opens through the global
                store (see canon Rule 13), this one is controlled straight by the caller. */}
            <DrawerShell
                isOpen={isMobileDrawerOpen}
                onOpenChange={onMobileDrawerOpenChange}
                placement="right"
                title="Mobile menu"

                body={() => <StackV gap={6} items={[() => drawerNav]} />}
            />
        </nav>
    )
}

