import React from "react"
import { cn } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH } from "@/components/frames/Stack"
import { useSidebarCollapsed } from "@/components/blocks/navigation/CollapsibleSidebar"
import { DESTINATION_ICON, DESTINATION_LABEL } from ".."
import type { SettingsNavItem } from ".."

/** Props for {@link DesktopNavRow}. */
export interface DesktopNavRowProps {
    /** Which destination this row is. */
    item: SettingsNavItem
    /** Whether this row's `href` is the one being viewed right now. */
    isActive: boolean
    /** Fired with the row's `href` when it is pressed. */
    onNavigate: (href: string) => void
}

/**
 * One destination row in the desktop rail: a leading icon + truncating label, icon-only
 * when `CollapsibleSidebar` is collapsed (read via `useSidebarCollapsed`, exported by that
 * composite so any nav-row content can drop to a rail without owning the flag itself).
 * A plain `<button>` rather than a HeroUI `Link` — see the file header's hand-roll call.
 */
export const DesktopNavRow = ({ item, isActive, onNavigate }: DesktopNavRowProps) => {
    const collapsed = useSidebarCollapsed()
    const Icon = DESTINATION_ICON[item.key]
    const rowContent = (
        <>
            <Icon aria-hidden focusable="false" className="size-5 shrink-0" />
            {!collapsed ? (
                <Typography
                    size="sm"
                    weight={isActive ? "medium" : undefined}
                    text={DESTINATION_LABEL[item.key]}
                    truncate

                />
            ) : null}
        </>
    )
    return (
        <button
            type="button"
            aria-label={DESTINATION_LABEL[item.key]}
            aria-current={isActive ? "page" : undefined}
            onClick={() => onNavigate(item.href)}
            className={cn(
                "w-full rounded-large text-start outline-none transition-colors focus-visible:ring-2 focus-visible:ring-accent",
                collapsed ? "px-2 py-2" : "px-3 py-2",
                isActive ? "bg-accent-soft text-accent-soft-foreground" : "text-foreground hover:bg-default/40",
            )}
        >
            <StackH gap={2} principle="icon-text" align="center" justify={collapsed ? "center" : "start"} items={[() => rowContent]}
                explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            />
        </button>
    )
}

import React from "react"
import { cn } from "@heroui/react"
import {
    BookmarkSimpleIcon,
    ChartBarIcon,
    CreditCardIcon,
    DesktopIcon,
    GraduationCapIcon,
    PaintBrushIcon,
    PencilSimpleIcon,
    ShieldCheckIcon,
    SlidersHorizontalIcon,
    StarIcon,
    WalletIcon,
} from "@phosphor-icons/react"
import { Divider } from "@/components/atoms/display/Divider"
import { Typography, type TypographyIcon } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { CollapsibleSidebar } from "@/components/blocks/navigation/CollapsibleSidebar"
import { DesktopNavRow } from "./DesktopNavRow"

/**
 * `SettingsSidebarNav` — the account-settings destination list, drawn as a
 * collapsible desktop rail and, below `@app-md`, a sticky horizontal pill bar.
 * Two structural leaves — `DesktopRail` (collapsible `Link`-shaped rows with a
 * divider between groups) and `MobilePillBar` (a flattened rounded-full chip
 * row). Both render the same component; only the container width differs, so
 * each story shows the branch its own `@app-md` query resolves to. `activeHref`
 * is data, so within each leaf it is a state.
 */

/** Every account-settings destination this rail can offer — the closed vocabulary the block owns. */
export type SettingsDestinationKey =
    | "editProfile"
    | "appearance"
    | "security"
    | "sessions"
    | "courseHistory"
    | "aiSettings"
    | "aiSubscription"
    | "aiUsage"
    | "bookmarks"
    | "membership"
    | "installments"

/** One settings destination — TYPED DOMAIN DATA only: which one, and where it navigates. */
export interface SettingsNavItem {
    /** Which destination this row is — drives its icon + label (block-owned table below). */
    key: SettingsDestinationKey
    /** Absolute href the row navigates to. */
    href: string
}

/**
 * A cluster of destinations rendered together. No `label` field: every real group is
 * unlabelled (see `src`'s `getSettingsGroups` — only a divider separates them), so adding
 * an unused caption prop would be inventing a case no screen asks for (§14d.3).
 */
export interface SettingsNavGroup {
    /** Stable React key for the group — not shown, only used for reconciliation + the divider count. */
    key: string
    /** The destinations in this group, in display order. */
    items: Array<SettingsNavItem>
}

/** Destination → label. The block's own wording (§14d.1), never handed in by the caller. */
export const DESTINATION_LABEL: Record<SettingsDestinationKey, string> = {
    editProfile: "Edit profile",
    appearance: "Appearance",
    security: "Security",
    sessions: "Login sessions",
    courseHistory: "Learning history",
    aiSettings: "AI settings",
    aiSubscription: "AI plan",
    aiUsage: "AI usage",
    bookmarks: "Saved",
    membership: "Membership plan",
    installments: "Installments",
}

/** Destination → icon. Same glyphs `src`'s `nav.tsx` maps, so porting this table reads as ONE control. */
export const DESTINATION_ICON: Record<SettingsDestinationKey, TypographyIcon> = {
    editProfile: PencilSimpleIcon,
    appearance: PaintBrushIcon,
    security: ShieldCheckIcon,
    sessions: DesktopIcon,
    courseHistory: GraduationCapIcon,
    aiSettings: SlidersHorizontalIcon,
    aiSubscription: CreditCardIcon,
    aiUsage: ChartBarIcon,
    bookmarks: BookmarkSimpleIcon,
    membership: StarIcon,
    installments: WalletIcon,
}

/** Props for {@link SettingsSidebarNav}. */
export interface SettingsSidebarNavProps {
    /** Grouped destinations, in display order. */
    groups: Array<SettingsNavGroup>
    /** Which destination's `href` is being viewed right now. */
    activeHref: string
    /** Fired with a destination's `href` when its row/pill is pressed. */
    onNavigate: (href: string) => void
    /** Heading shown atop the desktop rail (hidden while collapsed). */
    title: string
    /** Accessible label for the collapse toggle (expanded state). */
    collapseLabel: string
    /** Accessible label for the expand toggle (collapsed state). */
    expandLabel: string
    /** `localStorage` key the collapsed flag persists under, so the choice survives navigation. */
    storageKey: string
    /** Accessible name for the mobile pill nav landmark. Defaults to {@link title}. */
    mobileNavAriaLabel?: string
}

/**
 * The settings destination rail. See the file header for the reused `CollapsibleSidebar`
 * gap, the two still-inlined gaps, the enum-owned vocabulary, the `@app-md` port, and the
 * two structural leaves.
 *
 * @param props - {@link SettingsSidebarNavProps}
 */
const SettingsSidebarNav = ({
    groups,
    activeHref,
    onNavigate,
    title,
    collapseLabel,
    expandLabel,
    storageKey,
    mobileNavAriaLabel,
}: SettingsSidebarNavProps) => {
    // Mobile leaf flattens every group into one scroll strip — grouping only matters to the
    // desktop rail's dividers, the mobile bar has no room to spare on a section caption.
    const flatItems = groups.flatMap((group) => group.items)

    return (
        <div>
            {/* ── Desktop rail — hidden below @app-md; wraps the reused `CollapsibleSidebar`
                (chrome) with this block's own rows/dividers (domain content). */}
            <div className="hidden shrink-0 @app-md:sticky @app-md:top-16 @app-md:block @app-md:h-[calc(100dvh-4rem)]">
                <CollapsibleSidebar
                    title={title}
                    collapseLabel={collapseLabel}
                    expandLabel={expandLabel}
                    storageKey={storageKey}
                    className="h-full"


                >
                    {groups.map((group, index) => (
                        <React.Fragment key={group.key}>
                            {/* Divider above every group but the first — the inlined
                                `SidebarNavGroup` gap (see file header). Spacing between it
                                and its neighbours is owned by `CollapsibleSidebar`'s own
                                `StackV gap={4}`, not a margin on this Divider. */}
                            {index > 0 ? <Divider /> : null}
                            <StackV
                                gap={1}

                                items={group.items.map((item) => () => (
                                    <DesktopNavRow
                                        item={item}
                                        isActive={item.href === activeHref}
                                        onNavigate={onNavigate}

                                    />
                                ))}
                            />
                        </React.Fragment>
                    ))}
                </CollapsibleSidebar>
            </div>

            {/* ── Mobile pill bar — the OTHER leaf: chip-shaped buttons in a horizontal
                scroll strip, not the rail's row shape. Visible only below @app-md. */}
            <nav aria-label={mobileNavAriaLabel ?? title} className="sticky top-16 z-30 @app-md:hidden">
                <div className="overflow-x-auto border-b border-default bg-background/80 backdrop-blur-xl">
                    <StackH
                        gap={3}
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        padding={{ x: 4, y: 3 }}
                        items={flatItems.map((item) => () => {
                            const isActive = item.href === activeHref
                            const Icon = DESTINATION_ICON[item.key]
                            const pillContent = (
                                <>
                                    <Icon aria-hidden focusable="false" className="size-4 shrink-0" />
                                    <Typography size="sm" text={DESTINATION_LABEL[item.key]} noWrap />
                                </>
                            )
                            return (
                                <button
                                    type="button"
                                    aria-current={isActive ? "page" : undefined}
                                    onClick={() => onNavigate(item.href)}
                                    className={cn(
                                        "shrink-0 rounded-full border px-3 py-2 transition-colors",
                                        isActive ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
                                    )}
                                >
                                    <StackH gap={2} principle="icon-text" align="center" items={[() => pillContent]}
                                        explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                    />
                                </button>
                            )
                        })}
                    />
                </div>
            </nav>
        </div>
    )
}

export { SettingsSidebarNav }

import React from "react"
import type { ComponentType, SVGProps } from "react"
import {
    CalendarBlankIcon,
    GithubLogoIcon,
    GlobeIcon,
    HandshakeIcon,
    LinkedinLogoIcon,
    MapPinIcon,
    PencilSimpleIcon,
    UserCheckIcon,
    UserPlusIcon,
} from "@phosphor-icons/react"
import { Divider } from "@/components/atoms/display/Divider"
import { ProfileRankAvatar } from "./ProfileRankAvatar"
import { ProfileFollowers } from "./ProfileFollowers"
import { ProfileBadges } from "./ProfileBadges"
import { ShareProfileButton } from "./ShareProfileButton"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import type { ButtonVariant } from "@/components/atoms/buttons/Button"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `ProfileHero` — the identity sidebar for a person's profile page:
 * rank-framed avatar, name/@handle/role, bio, location + work-mode, follower
 * and badge social proof, one primary CTA (hire/follow/edit) + share, and a
 * github/linkedin/website/joined meta list. Composed from `SurfaceCard` around
 * `StackV`/`StackH`/`Cluster` holding `Avatar`/`Typography`/`Chip`/`Button`/
 * `Divider` plus `EnumChip`/`InlineIconLabel`. Two leaves: `Default` (every
 * optional row present; CTA/skeleton/follow-state are content states) and
 * `Minimal` (no rank/role/bio/location/work-mode/badges/social links — losing
 * those removes real nodes, earning its own leaf).
 */

/** An icon passed as a COMPONENT (e.g. a Phosphor `*Icon`), rendered at the tile's own scale. Declared locally per atom convention (§5.0) rather than importing one library's type. */
type IconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/** How this person works — the block owns the label wording (§14d.1), the caller only says which one. */
export type ProfileWorkMode = "remote" | "onsite" | "hybrid"

/** External profile links. Each is optional; an absent one simply drops its meta row. */
export interface ProfileSocialLinks {
    /** GitHub profile URL. */
    github?: string
    /** LinkedIn profile URL. */
    linkedin?: string
    /** Personal site/portfolio URL. */
    website?: string
}

/** One achievement/verification badge earned by this person. */
export interface ProfileBadge {
    /** Stable id — used as the chip's React key. */
    id: string
    /** Badge label, already worded by the caller's domain (e.g. "Top mentor"). */
    label: string
    /** Optional leading glyph for the badge chip. */
    icon?: IconComponent
}

/** The person this hero profiles — plain data, the block builds the sidebar from it. */
export interface ProfileHeroUser {
    /** Stable id (not rendered; kept for parity with other domain-user shapes). */
    id: string
    /** Full display name. */
    fullName: string
    /** Handle WITHOUT the leading `@` — the block adds it (§14d.1). */
    handle: string
    /** Role/title line under the name. Row disappears when absent. */
    roleTitle?: string
    /** Short bio/about text. Row disappears when absent. */
    bio?: string
    /** Free-text location (e.g. "Hanoi, Vietnam"). Row disappears when absent. */
    location?: string
    /** How this person works. Row disappears when absent. */
    workMode?: ProfileWorkMode
    /** Photo URL. Empty/missing → `Avatar`'s own fallback chain, never a blank frame. */
    avatarUrl?: string
    /** Leaderboard-style standing (1 = top). Absent → no rank frame/caption at all. */
    rank?: number
    /** Total followers. Absent renders as `0` (a real, known count of nothing). */
    followersCount?: number
    /** Achievement badges earned. Empty/absent → the badges row disappears entirely. */
    badges?: ReadonlyArray<ProfileBadge>
    /** ISO date string this person joined. Required — every profile has one. */
    joinedAt: string
    /** External links. Absent/all-empty → the social rows of the meta list disappear. */
    social?: ProfileSocialLinks
}

/** Props for {@link ProfileHero}. */
export interface ProfileHeroProps {
    /** The profiled person. */
    user: ProfileHeroUser
    /** `true` → the viewer IS this person: the primary CTA becomes "Edit profile", follow/hire never show. */
    isSelf?: boolean
    /** `true` (and not `isSelf`) → the primary CTA becomes "Hire me" instead of follow. */
    canHire?: boolean
    /** Whether the viewer already follows this person. Ignored when `isSelf`/`canHire`. */
    following?: boolean
    /** `true` → the follow CTA shows its busy state while the toggle is in flight. */
    isFollowPending?: boolean
    /** Fired when the viewer toggles follow (only reachable when neither `isSelf` nor `canHire`). */
    onToggleFollow?: () => void
    /** Fired when the viewer presses "Hire me" (only reachable when `canHire` and not `isSelf`). See file header, judgement call 3. */
    onHire?: () => void
    /** Fired when the profile owner presses "Edit profile" (only reachable when `isSelf`). */
    onEdit?: () => void
    /** Fired when the share action is pressed. */
    onShare?: () => void
    /** `true` → every real part switches to its own shimmer; the profile stops accepting presses. */
    isSkeleton?: boolean
}

interface PrimaryAction {
    label: string
    variant: ButtonVariant
    prefixIcon: IconComponent
    onPress?: () => void
    isPending?: boolean
}

/** Inputs {@link resolvePrimaryAction} needs to pick the one CTA slot. */
interface ResolvePrimaryActionParams {
    isSelf: boolean
    canHire: boolean
    following: boolean
    isFollowPending: boolean
    onEdit?: () => void
    onHire?: () => void
    onToggleFollow?: () => void
}

const resolvePrimaryAction = (params: ResolvePrimaryActionParams): PrimaryAction => {
    const { isSelf, canHire, following, isFollowPending, onEdit, onHire, onToggleFollow } = params
    if (isSelf) {
        return { label: "Edit profile", variant: "secondary", prefixIcon: PencilSimpleIcon, onPress: onEdit }
    }
    if (canHire) {
        return { label: "Hire me", variant: "primary", prefixIcon: HandshakeIcon, onPress: onHire }
    }
    return {
        label: following ? "Following" : "Follow",
        variant: following ? "secondary" : "primary",
        prefixIcon: following ? UserCheckIcon : UserPlusIcon,
        onPress: onToggleFollow,
        isPending: isFollowPending,
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Meta list — social links (as text-links) + joined date (plain).
// ─────────────────────────────────────────────────────────────────────────────

/** One entry of the social meta list — the block's own icon + label per platform. */
interface ProfileSocialMetaEntry {
    key: keyof ProfileSocialLinks
    icon: IconComponent
    label: string
}

/** The block's own label per platform (§14d.1) — the caller only supplies the URL. */
const SOCIAL_META: ReadonlyArray<ProfileSocialMetaEntry> = [
    { key: "github", icon: GithubLogoIcon, label: "GitHub" },
    { key: "linkedin", icon: LinkedinLogoIcon, label: "LinkedIn" },
    { key: "website", icon: GlobeIcon, label: "Personal site" },
]

/** `Intl`-formatted "Month M, YYYY" from an ISO date string. Empty input → empty string (no bogus date printed). */
const formatJoinedDate = (isoDate: string): string => {
    const date = new Date(isoDate)
    if (Number.isNaN(date.getTime())) return ""
    return new Intl.DateTimeFormat("vi-VN", { month: "long", year: "numeric" }).format(date)
}

/** How this person works, worded by the block (§14d.1). */
const WORK_MODE_MAP: Record<ProfileWorkMode, EnumChipEntry> = {
    remote: { label: "Remote" },
    onsite: { label: "Onsite" },
    hybrid: { label: "Hybrid", color: "accent" },
}

/**
 * The bare identity sidebar. See the file header for the reuse contract and the
 * four judgement calls.
 *
 * @param props - {@link ProfileHeroProps}
 */
const ProfileHero = ({
    user,
    isSelf = false,
    canHire = false,
    following = false,
    isFollowPending = false,
    onToggleFollow,
    onHire,
    onEdit,
    onShare,
    isSkeleton = false,
}: ProfileHeroProps) => {
    const { fullName, handle, roleTitle, bio, location, workMode, avatarUrl, rank, followersCount, badges, joinedAt, social } = user

    const action = resolvePrimaryAction({ isSelf, canHire, following, isFollowPending, onEdit, onHire, onToggleFollow })
    const hasBadgesRow = isSkeleton || Boolean(badges && badges.length > 0)
    const hasLocationRow = isSkeleton || Boolean(location) || Boolean(workMode)

    const socialLinks = social ?? {}
    const socialEntries = SOCIAL_META.filter((entry) => Boolean(socialLinks[entry.key]))
    const hasMetaList = isSkeleton || socialEntries.length > 0 || Boolean(joinedAt)

    const nameBlock = (
        <>
            <Typography
                size="h5"
                weight="bold"
                align="center"
                isSkeleton={isSkeleton}
                text={fullName}

            />
            <Typography
                size="sm"
                color="muted"
                align="center"
                isSkeleton={isSkeleton}
                text={isSkeleton ? undefined : `@${handle}`}

            />
            {isSkeleton || roleTitle ? (
                <Typography
                    size="sm"
                    weight="medium"
                    align="center"
                    isSkeleton={isSkeleton}
                    text={roleTitle}

                />
            ) : null}
        </>
    )

    const identitySection = (
        <>
            <ProfileRankAvatar
                name={fullName}
                avatarUrl={avatarUrl}
                rank={rank}
                isSkeleton={isSkeleton}

            />
            <StackV gap={1} principle="name-handle"
                explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                align="center" isSkeleton={isSkeleton} items={[() => nameBlock]}  />
        </>
    )

    const statsRow = (
        <>
            <ProfileFollowers followersCount={followersCount} isSkeleton={isSkeleton} />
            {hasBadgesRow ? (
                <ProfileBadges badges={badges} isSkeleton={isSkeleton} />
            ) : null}
        </>
    )

    const actionsRow = (
        <>
            <Button
                classNames={["flex-1"]}
                variant={action.variant}
                label={action.label}
                prefixIcon={action.prefixIcon}
                onPress={action.onPress}
                isPending={action.isPending}
                isSkeleton={isSkeleton}

            />
            <ShareProfileButton onShare={onShare} isSkeleton={isSkeleton} />
        </>
    )

    const metaList = (
        <>
            {(isSkeleton ? SOCIAL_META : socialEntries).map((entry) => {
                const socialRow = (
                    <>
                        <span aria-hidden className="inline-flex shrink-0 text-muted [&_svg]:size-4">
                            <entry.icon />
                        </span>
                        <Typography
                            size="xs"
                            isLink={!isSkeleton}
                            href={isSkeleton ? undefined : socialLinks[entry.key]}
                            isSkeleton={isSkeleton}
                            truncate
                            text={isSkeleton ? undefined : entry.label}

                        />
                    </>
                )
                return <StackH key={entry.key} gap={2} isSkeleton={isSkeleton} items={[() => socialRow]} />
            })}
            <InlineIconLabel
                icon={CalendarBlankIcon}
                tone="default"
                isSkeleton={isSkeleton}
                label={isSkeleton ? undefined : `Joined ${formatJoinedDate(joinedAt)}`}
            />
        </>
    )

    const metaSection = hasMetaList ? (
        <>
            <Divider />
            <StackV gap={4} isSkeleton={isSkeleton} items={[() => metaList]} />
        </>
    ) : null

    const cardBody = (
        <>
            <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                align="center" isSkeleton={isSkeleton} items={[() => identitySection]}  />

            {isSkeleton || bio ? (
                <Typography
                    size="sm"
                    color="muted"
                    align="center"
                    lineClamp={3}
                    isSkeleton={isSkeleton}
                    text={bio}

                />
            ) : null}

            {hasLocationRow ? (
                <Cluster
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    justify="center"
                    items={[
                        ...(isSkeleton || location
                            ? [
                                () => (
                                    <InlineIconLabel
                                        icon={MapPinIcon}
                                        isSkeleton={isSkeleton}
                                        label={location}
                                    />
                                ),
                            ]
                            : []),
                        ...(isSkeleton || workMode
                            ? [
                                () => (
                                    <EnumChip
                                        value={(workMode ?? "remote") as ProfileWorkMode}
                                        map={WORK_MODE_MAP}
                                        isSkeleton={isSkeleton}
                                    />
                                ),
                            ]
                            : []),
                    ]}
                />
            ) : null}

            <StackH gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                divider isSkeleton={isSkeleton} items={[() => statsRow]}  />

            <StackH gap={3} isSkeleton={isSkeleton} items={[() => actionsRow]} />

            {metaSection}
        </>
    )

    return (
        <div>
            <SurfaceCard


                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => cardBody]} />}
            />
        </div>
    )
}

