    /** The card this outcome belongs to (sent to the server for scoring + weak-tags). */
    cardId: string
    /** Ratio of blanks filled correctly (0..1), or null for a fallback card without a cloze. */
    coverageRatio: number | null
    /** Blanks filled correctly this card had (0 for a fallback card without a cloze). */
    correctBlanks: number
    /** Total cloze blanks this card had (0 for a fallback card without a cloze). */
    totalBlanks: number
    /** Whether the learner got the card fully right without a hint (mastery signal). */
    correct: boolean
    /** XP this card contributed to the local estimate. */
    xp: number
}

/** Fisher–Yates shuffle (returns a new array; interleaves cards across decks/tags). */
const shuffle = <T,>(input: Array<T>): Array<T> => {
    const array = [...input]
    for (let i = array.length - 1; i > 0; i -= 1) {
        const j = Math.floor(Math.random() * (i + 1))
        ;[array[i], array[j]] = [array[j], array[i]]
    }
    return array
}

/**
 * "Quick Quiz" — a non-AI, self-graded, gamified flashcard cloze quiz over a
 * course. The learner picks a mode + level, then for each drawn card fills the
 * blanks (key terms the author marked) from a word bank of correct terms +
 * sibling-card distractors, checks the answer objectively, reads the full model
 * answer, and self-grades with SM-2 (which reschedules the card). A combo tracks
 * momentum; the recap frames the run by mastery and grants leaderboard XP once
 * per session. The setup's data states go through {@link FlashcardStatsStrip}.
 * @param props - {@link QuizSessionProps}
 */
export const QuizSession = ({ courseId, className, resumeSessionId }: QuizSessionProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    const searchParams = useSearchParams()
    const runGraphQL = useGraphQLWithToast()
    // trial-vs-enrolled gating (enroll upsell + AI Mock Interview readiness) now lives
    // in the converged `FlashcardQuizResult` surface, which reads it from redux itself.
    const displayId = useAppSelector((state) => state.course.displayId)
    // course name for the shared WorkSessionHeader's identity chip
    const course = useAppSelector((state) => state.course.entity)
    // quiz cards are enrolled-only → send the course header for the backend guard
    const courseHeaders = useMemo(
        () => ({ [GraphQLHeadersKey.XCourseId]: courseId }),
        [courseId],
    )

    // mastery ("Mastery level") + the pool of decks to draw cards from
    const decksSwr = useSWR(
        ["flashcard-decks-by-course", courseId],
        async () => {
            const response = await queryFlashcardDecksByCourse({
                request: { courseId },
                headers: courseHeaders,
            })
            return response.data?.flashcardDecksByCourse.data ?? null
        },
    )
    const decks = decksSwr.data

    // today's due-card ids — same SWR key/shape `DueReviewHero` already reads, so
    // the scope-picker's "Only cards due for review" and `startSession`'s draw-time filter
    // (below) share one fetch. `dueCount` also gates/dims the scope option when
    // nothing is due (mirrors `FlashcardReviewModeModal`'s `dueDisabled`).
    const dueSwr = useSWR(
        ["my-due-flashcards", courseId, DUE_REVIEW_LIMIT],
        async () => {
            const response = await queryMyDueFlashcards({ request: { courseId, limit: DUE_REVIEW_LIMIT } })
            return response.data?.myDueFlashcards.data ?? null
        },
    )
    const dueCardIds = useMemo(
        () => new Set((dueSwr.data?.cards ?? []).map((dueCard) => dueCard.cardId)),
        [dueSwr.data],
    )
    const dueDisabled = (dueSwr.data?.dueCount ?? 0) <= 0
    useEffect(() => {
        if (dueDisabled) {
            setScope("all")
        }
    }, [dueDisabled])

    // refreshed after a session grants XP (the setup's progress zone reads its own
    // streak from `FlashcardStatsStrip` instead)
    const weeklyStatsSwr = useQueryMyWeeklyStatsSwr()

    const runComplete = useMutateCompleteFlashcardQuizSessionSwr()
    const runStart = useMutateStartFlashcardQuizSessionSwr()
    const runSyncProgress = useMutateSyncFlashcardQuizSessionProgressSwr()
    // read BOTH by the setup screen's resume card (when NOT already resuming) and the
    // rehydrate effect below (when `resumeSessionId` IS present) — mirrors
    // `MockInterviewSession`'s single `inProgressSessionSwr` read.
    const inProgressSessionSwr = useQueryMyInProgressFlashcardQuizSessionSwr(courseId)

    // total card count across the course's decks — gates the setup CTA
    const totalCards = useMemo(
        () => (decks ?? []).reduce((sum, deck) => sum + (deck.cards?.length ?? 0), 0),
        [decks],
    )

    // shared-layout "fly into the blank" animation (word-bank chip ↔ blank chip)
    // is disabled under prefers-reduced-motion — same idiom as CollapsibleSidebar.
    const reduceMotion = useReducedMotion()

    // ── session state ────────────────────────────────────────────────────
    const [phase, setPhase] = useState<QuizPhase>("setup")
    // which setup tab is active ("Begin" / "History" / "Stats") — setup phase only.
    // Seeded from `?tab=` so a shared/refreshed link lands back on the same tab (mirrors
    // MockInterviewSession's own setupTab + `layouts/dashboard-hub.md`'s "?tab= must be
    // shareable" precedent) — "begin" is the implicit default, never written to the URL.
    const [setupTab, setSetupTab] = useState<"begin" | "history" | "stats">(() => {
        const initial = searchParams.get("tab")
        return initial === "history" || initial === "stats" ? initial : "begin"
    })
    const [mode, setMode] = useState<QuizMode>("quick")
    const [level, setLevel] = useState<string | null>(null)
    // learner-chosen name for this run, set at setup ("Practice config") — optional;
    // blank falls back to a TIME-BASED display name derived from `updatedAt` once
    // the session exists (see `sessionDisplayName`), never random-generated.
    const [sessionName, setSessionName] = useState("")
    // "Review all" (draw from the whole pool) vs "Only cards due for review" (draw only from
    // today's due queue) — same 2 options + wording as `FlashcardReviewModeModal`
    // (teacher 2026-07-13: "add review-all and only-cards-due to the practice config").
    const [scope, setScope] = useState<"all" | "due">("all")
    // cards drawn for the current run
    const [sessionCards, setSessionCards] = useState<Array<QuizCard>>([])
    // zero-based index of the current card
    const [index, setIndex] = useState(0)
    // the learner's chosen term per blank (null = still empty)
    const [filled, setFilled] = useState<Array<string | null>>([])
    // true once the learner checked the filled cloze (locks it, reveals correctness)
    const [checked, setChecked] = useState(false)
    // true once the full model answer is revealed (after checking)
    const [showAnswer, setShowAnswer] = useState(false)
    // true while an SM-2 grade is in flight (blocks the rating bar)
    const [rating, setRating] = useState(false)
    // per-card outcomes gathered this run
    const [results, setResults] = useState<Array<CardResult>>([])
    // in-session combo (consecutive well-answered cards) — drives the active HUD chip
    const [combo, setCombo] = useState(0)
    // confirm-before-exit for the two irreversible active-session actions, mirroring
    // MockInterviewSession: "leave" (Exit — abandon this run) · "endEarly" (End
    // early — grade with the cards done so far). null = no dialog open.
    const [confirmAction, setConfirmAction] = useState<null | "leave" | "endEarly">(null)
    // true while `startSession` is drawing + persisting a fresh run — drives the
    // "Start practice" button's own isPending (stays ON this screen; only the
    // eventual navigation to `/quiz/[sessionId]` leaves it, restructured 2026-07-09).
    const [starting, setStarting] = useState(false)
    // set when `startSession` couldn't produce a playable session (no cards at the
    // chosen level, or the persist call failed) — shown inline on the setup screen;
    // the run never leaves `setup` until a session is actually created.
    const [startError, setStartError] = useState<string | null>(null)
    // client-generated id shared by this run → idempotent XP grant
    const sessionId = useRef<string | null>(null)
    // guards the one-shot completion mutation on entering the recap
    const completedRef = useRef(false)
    // guards the one-shot resume rehydration to run at most once per mounted instance
    const resumeAttemptedRef = useRef(false)
    // set when `resumeSessionId` couldn't be resumed (no matching session / expired
    // past its 60min TTL) — shown as an inline note on the setup screen it falls back to
    const [resumeError, setResumeError] = useState<string | null>(null)
    // server-issued deadline for THIS run (createdAt + duration) — set on start AND
    // on resume rehydrate; drives the WorkSessionHeader countdown below, same
    // `deadlineAt` contract as Mock Interview's own HUD (never a local clock start).
    const [deadlineAt, setDeadlineAt] = useState<string | null>(null)
    const [remainingSeconds, setRemainingSeconds] = useState<number | null>(null)
    // dummy tick to force the setup screen's resume-card "N minutes left" to recompute
    // every 30s while it's on screen — same idiom as MockInterviewSession's own
    // `resumeCountdownTick` (the minutes value itself is computed inline in render).
    const [, setResumeCountdownTick] = useState(0)

    // the setup screen's mode picker drives this pre-build; once cards are actually
    // drawn (fresh OR resumed), the real count wins — a resumed run's card count
    // depends on whichever mode it was originally started with, not the setup
    // screen's current (unrelated) selection.
    const sessionLength = sessionCards.length > 0 ? sessionCards.length : MODE_LENGTH[mode]

    const card = sessionCards[index]

    // SM-2 grade buttons for the current card: localized label + next-interval
    // preview ("4 days") computed server-side from the card's current state
    const ratingOptions = useMemo(() => {
        const intervals = card?.nextIntervals
        // map a grade to its previewed next-interval in days
        const daysForGrade = (grade: number): number | undefined => {
            if (!intervals) {
                return undefined
            }
            return [intervals.again, intervals.hard, intervals.good, intervals.easy][grade]
        }
        return SM2_GRADES.map((grade) => {
            const days = daysForGrade(grade.grade)
            return {
                grade: grade.grade,
                label: t(grade.labelKey),
                hint: days === undefined ? undefined : t("flashcard.review.intervalDays", { count: days }),
            }
        })
    }, [t, card])

    // fetch the full cards of every deck (self-grading needs a model answer to compare
    // against). Each deck is fetched independently (allSettled) so ONE deck failing
    // (e.g. missing from the Elasticsearch index the single-deck read serves from —
    // see `FlashcardDeckReadService.getById`) can't silently empty the whole pool:
    // the caller just draws from whichever decks DID resolve. Shared by a FRESH start
    // (draws + shuffles) and a resume (looks the persisted `cardIds` up by id).
    const fetchCardPool = useCallback(async () => {
        const settled = await Promise.allSettled(
            (decks ?? []).map(async (deck) => {
                const response = await queryFlashcardDeck({
                    request: { flashcardDeckId: deck.id },
                    headers: courseHeaders,
                })
                const payload = response.data?.flashcardDeck
                if (!payload?.success) {
                    throw new Error(payload?.message ?? "flashcard deck fetch failed")
                }
                return (payload.data?.cards ?? []).map((card) => ({ ...card, deckId: deck.id }))
            }),
        )
        const anyDeckFailed = settled.some((result) => result.status === "rejected")
        const deckPayloads = settled
            .filter((result) => result.status === "fulfilled")
            .map((result) => result.value)
        const pool: Array<QuizCard> = deckPayloads
            .flat()
            .filter((card) => Boolean(card.answer))
            .map((card) => ({ ...card, keywords: extractMarkerTerms(card.answer) }))
        return { pool, anyDeckFailed }
    }, [decks, courseHeaders])

    // draw a fresh run: pool + filter by level + shuffle, persist it server-side,
    // THEN navigate to the resumable `/quiz/[sessionId]` route — stays on THIS
    // (setup) screen the whole time, pending only on the CTA itself, per the teacher's
    // 2026-07-09 correction ("create the session first, then load into the quiz with its id" — no
    // more instant phase flip to a building-skeleton screen, and no more silent
    // local/non-resumable fallback when the persist call fails: a real failure
    // now surfaces inline instead of quietly degrading).
    const startSession = useCallback(async () => {
        if (!decks || decks.length === 0 || starting) {
            return
        }
        setStarting(true)
        setStartError(null)
        setResumeError(null)
        try {
            const { pool, anyDeckFailed } = await fetchCardPool()
            const drawn = shuffle(
                pool
                    .filter((card) => level === null || card.level === level)
                    .filter((card) => scope !== "due" || dueCardIds.has(card.id)),
            ).slice(0, sessionLength)

            if (drawn.length === 0) {
                // an empty pool only means "no cards at this level" when every deck
                // fetch actually succeeded — otherwise it's a load failure in disguise
                setStartError(
                    anyDeckFailed
                        ? t("flashcard.quiz.sessionLoadErrorTitle")
                        : scope === "due"
                            ? t("flashcard.quiz.emptyAtScope")
                            : t("flashcard.quiz.emptyAtLevel"),
                )
                setStarting(false)
                return
            }

            // `mode`/`level` are REQUIRED (non-null) on the backend's
            // StartFlashcardQuizSessionRequest (see start-flashcard-quiz-session/
            // graphql-types/request.ts) — omitting them fails GraphQL input
            // validation before the resolver even runs (fixed 2026-07-09).
            const started = await runStart.trigger({
                request: {
                    courseId,
                    cardIds: drawn.map((card) => card.id),
                    mode,
                    level,
                    name: sessionName.trim() || undefined,
                },
                headers: courseHeaders,
            }).catch(() => null)
            const startedId = started?.data?.startFlashcardQuizSession.data?.sessionId
            if (!startedId || !displayId) {
                setStartError(t("flashcard.quiz.sessionLoadErrorTitle"))
                setStarting(false)
                return
            }
            // prime the in-progress cache with the just-created session BEFORE
            // navigating, so the fresh page that mounts at `/quiz/[sessionId]` reads
            // it (not the stale `null` this screen's own resume check cached) and
            // rehydrates cleanly instead of flashing "resume failed".
            await inProgressSessionSwr.mutate()
            router.push(
                pathConfig().locale(locale).course(displayId).learn()
                    .flashcards().quiz(startedId).build(),
            )
            // deliberately no `setStarting(false)` here — this instance is about to
            // be unmounted by the navigation, so the button stays visibly pending
            // right up until the destination page takes over.
        } catch {
            setStartError(t("flashcard.quiz.sessionLoadErrorTitle"))
            setStarting(false)
        }
    }, [decks, starting, level, scope, dueCardIds, sessionLength, t, courseHeaders, courseId, mode, sessionName, runStart, inProgressSessionSwr, displayId, locale, router])

    // "Exit" — leaves the active run for the setup screen. No confirm modal (unlike
    // Mock Interview's leave, which is destructive/abandon-ungraded): a quiz run is
    // persisted server-side (`syncFlashcardQuizSessionProgress`) so navigating away
    // just resumes later from the same card (teacher 2026-07-09: "both the review and
    // quiz parts have no back button").
    const exitToSetup = useCallback(() => {
        router.push(
            `${pathConfig().locale(locale).course(displayId).learn().flashcards().build()}/quiz`,
        )
    }, [router, locale, displayId])

    // finalize the run: send the per-card breakdown so the server re-derives coverage/XP
    // itself (no client-trusted aggregate), grant XP once (idempotent), then show the recap.
    // Defined here (not just above `commitCard`) so the resume effect below can call it too
    // (2026-07-12, mirrors the same move made for `MockInterviewSession`'s `renderWorkHeader`).
    const finish = useCallback(
        async (finalResults: Array<CardResult>) => {
            setPhase("recap")
            if (completedRef.current || !sessionId.current) {
                return
            }
            completedRef.current = true
            const answers = finalResults.map((result) => ({
                cardId: result.cardId,
                correctBlanks: result.correctBlanks,
                totalBlanks: result.totalBlanks,
            }))
            let awarded = 0
            await runGraphQL(
                async () => {
                    const response = await runComplete.trigger({
                        request: {
                            sessionId: sessionId.current as string,
                            courseId,
                            answers,
                        },
                        headers: courseHeaders,
                    })
                    const payload = response.data?.completeFlashcardQuizSession
                    awarded = payload?.data?.xpEarned ?? 0
                    return (
                        payload ?? {
                            success: false,
                            message: t("flashcard.review.error"),
                        }
                    )
                },
                { showSuccessToast: false },
            )
            if (awarded > 0) {
                // refresh the streak/XP chip now that this run counted
                void weeklyStatsSwr.mutate()
            }
            // Navigate to the dedicated result route instead of rendering the
            // result inline here — "done" is now answered by the URL, not
            // re-derived client-side (see result/page.tsx doc for root cause).
            if (displayId) {
                router.replace(
                    pathConfig()
                        .locale(locale)
                        .course(displayId)
                        .learn()
                        .flashcards()
                        .quiz(sessionId.current as string)
                        .result()
                        .build(),
                )
            }
        },
        [runComplete, runGraphQL, courseId, courseHeaders, t, weeklyStatsSwr, router, locale, displayId],
    )

    // resume, on mount, when reached via the dedicated `flashcards/quiz/sessions/[sessionId]`
    // route — waits for both the deck pool AND the in-progress query to settle, then
    // either rehydrates straight into the active phase at the persisted card/index or
    // falls back to setup with an inline error. Runs at most ONCE per mounted instance.
    useEffect(() => {
        if (!resumeSessionId || resumeAttemptedRef.current || !decks || inProgressSessionSwr.isLoading) {
            return
        }
        resumeAttemptedRef.current = true
        const data = inProgressSessionSwr.data
        if (!data || data.sessionId !== resumeSessionId) {
            setResumeError(t("flashcard.quiz.resumeFailed"))
            setPhase("setup")
            return
        }
        void (async () => {
            const { pool } = await fetchCardPool()
            const cardById = new Map(pool.map((quizCard) => [quizCard.id, quizCard]))
            const restoredCards = data.cardIds
                .map((cardId) => cardById.get(cardId))
                .filter((quizCard): quizCard is QuizCard => Boolean(quizCard))
            if (restoredCards.length === 0) {
                setResumeError(t("flashcard.quiz.resumeFailed"))
                setPhase("setup")
                return
            }
            const restoredResults: Array<CardResult> = data.results.map((result) => {
                const coverageRatio = result.totalBlanks > 0 ? result.correctBlanks / result.totalBlanks : null
                return {
                    cardId: result.cardId,
                    coverageRatio,
                    correctBlanks: result.correctBlanks,
                    totalBlanks: result.totalBlanks,
                    correct: coverageRatio === 1,
                    xp: coverageRatio !== null ? result.correctBlanks * XP_PER_CORRECT_BLANK : 0,
                }
            })
            sessionId.current = resumeSessionId
            setDeadlineAt(data.deadlineAt)
            setSessionCards(restoredCards)
            setCombo(0)
            setResumeError(null)

            // every card already has a recorded outcome — the run WAS finished,
            // but `status` never flipped to "completed" (the earlier `finish()`
            // call never landed server-side for whatever reason — network drop,
            // a duplicate-submit race, etc. — 2026-07-12, teacher: "submitted, but
            // refreshing goes back to the last question"). `currentIndex` alone can't tell "about to answer
            // the LAST card" from "just answered it" apart — both persist the
            // same last-valid-index value — only `results` coverage can. Retry
            // completion instead of silently resuming into the (already
            // answered) last card again.
            if (restoredResults.length >= restoredCards.length) {
                completedRef.current = false
                setResults(restoredResults)
                setIndex(restoredCards.length - 1)
                void finish(restoredResults)
                return
            }

            setIndex(Math.min(data.currentIndex, restoredCards.length - 1))
            setResults(restoredResults)
            completedRef.current = false
            setPhase("active")
        })()
    }, [resumeSessionId, decks, inProgressSessionSwr.isLoading, inProgressSessionSwr.data, fetchCardPool, t, finish])

    // "session time limit" — ticks every second while the run is active, counting
    // DOWN to the server-issued `deadlineAt` (never a local clock start). Mirrors
    // `MockInterviewSession`'s own countdown effect (teacher 2026-07-11: "add a
    // 60-minute time limit per session" — the deadline itself was already server-enforced
    // via `FLASHCARD_QUIZ_SESSION_DURATION_MS`; this makes it VISIBLE in the HUD).
    useEffect(() => {
        if (phase !== "active" || !deadlineAt) {
            return
        }
        const deadlineMs = new Date(deadlineAt).getTime()
        const tick = () => {
            setRemainingSeconds(Math.max(0, Math.ceil((deadlineMs - Date.now()) / 1000)))
        }
        tick()
        const id = window.setInterval(tick, 1000)
        return () => window.clearInterval(id)
    }, [phase, deadlineAt])

    // resume-card countdown (setup screen) — coarse 30s tick, only while there's
    // an actual resumable session to show a deadline for. Mirrors
    // MockInterviewSession's own resume-card countdown idiom.
    useEffect(() => {
        if (phase !== "setup" || !inProgressSessionSwr.data) {
            return
        }
        const id = window.setInterval(() => setResumeCountdownTick((previous) => previous + 1), 30_000)
        return () => window.clearInterval(id)
    }, [phase, inProgressSessionSwr.data])

    // mirror the setup tab into the URL (`?tab=history` / `?tab=stats`) — same technique
    // as MockInterviewSession's own setupTab mirror, so "History"/"Stats" are
    // shareable/refresh-safe links. "begin" (the default) is never written, keeping the
    // common-case URL clean.
    useEffect(() => {
        const want = setupTab === "begin" ? null : setupTab
        if (searchParams.get("tab") === want) {
            return
        }
        const params = new URLSearchParams(searchParams.toString())
        if (want) {
            params.set("tab", want)
        } else {
            params.delete("tab")
        }
        const qs = params.toString()
        router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false })
    }, [setupTab, pathname, searchParams, router])

    // distractor pool: sibling cards' key terms, closest-topic first (in the style of
    // Duolingo/Quizlet drawing from the session's own vocab) — same TAG, then
    // same DECK (still one coherent topic even without a shared tag), then the
    // whole session as a last resort. Without the deck tier, a thin same-tag
    // draw fell straight through to the WHOLE session/course pool, which is how
    // an unrelated term (e.g. a SQL clause) ended up in a NestJS DI question's
    // word bank (teacher 2026-07-11 bug report).
    const distractorPool = useMemo(() => {
        if (!card) {
            return []
        }
        const others = sessionCards.filter((_, position) => position !== index)
        const sameTag = others.filter((other) =>
            (other.tags ?? []).some((tag) => (card.tags ?? []).includes(tag)),
        )
        const sameDeck = others.filter((other) => other.deckId === card.deckId)
        const source = sameTag.length >= 2 ? sameTag : sameDeck.length >= 2 ? sameDeck : others
        return [...new Set(source.flatMap((other) => other.keywords))]
    }, [card, sessionCards, index])

    // the cloze for the current card (null → fall back to a plain flip +
    // self-grade — only when the card itself has no clozable key terms;
    // "Quick Quiz" and "Study Cards" are unrelated features, so this is NOT a
    // learner-facing method choice, just a per-card content fallback).
    const cloze = useMemo<ClozeQuestion | null>(
        () =>
            card
                ? buildCloze({
                    answer: card.answer ?? "",
                    distractorPool,
                })
                : null,
        [card, distractorPool],
    )

    // reset the per-card interaction whenever the card (hence its cloze) changes
    useEffect(() => {
        setFilled(cloze ? Array(cloze.blanks.length).fill(null) : [])
        setChecked(false)
        setShowAnswer(false)
    }, [cloze])

    // place a bank term into the first empty blank (ignored once checked / already used)
    const placeTerm = useCallback(
        (term: string) => {
            if (checked) {
                return
            }
            setFilled((current) => {
                if (current.includes(term)) {
                    return current
                }
                const slot = current.indexOf(null)
                if (slot === -1) {
                    return current
                }
                const next = [...current]
                next[slot] = term
                return next
            })
        },
        [checked],
    )

    // clear a filled blank (returns its term to the bank)
    const clearBlank = useCallback(
        (blankIndex: number) => {
            if (checked) {
                return
            }
            setFilled((current) => {
                const next = [...current]
                next[blankIndex] = null
                return next
            })
        },
        [checked],
    )

    // record the current card's outcome + combo, reschedule via SM-2, then advance
    const commitCard = useCallback(
        async (grade: number, coverageRatio: number | null) => {
            if (!card) {
                return
            }
            setRating(true)
            // a success toast per card would be noise — only surface failures
            const ok = await runGraphQL(
                async () => {
                    const response = await mutateReviewFlashcard({
                        request: { cardId: card.id, grade },
                    })
                    return (
                        response.data?.reviewFlashcard ?? {
                            success: false,
                            message: t("flashcard.review.error"),
                        }
                    )
                },
                { showSuccessToast: false },
            )
            setRating(false)
            if (!ok) {
                return
            }
            const correct = coverageRatio === 1 || (coverageRatio === null && grade >= COMBO_GRADE_THRESHOLD)
            const keptCombo =
                (coverageRatio !== null && coverageRatio >= COMBO_COVERAGE_THRESHOLD)
                || grade >= COMBO_GRADE_THRESHOLD
            // this card's raw blank counts — sent to the server, which re-derives coverage/XP
            // itself (no client-trusted aggregate); a fallback (no-cloze) card sends 0/0
            const totalBlanks = coverageRatio !== null ? (cloze?.blanks.length ?? 0) : 0
            const correctBlanks = coverageRatio !== null ? Math.round(coverageRatio * totalBlanks) : 0
            const xp =
                coverageRatio !== null
                    ? correctBlanks * XP_PER_CORRECT_BLANK
                    : grade >= COMBO_GRADE_THRESHOLD
                        ? XP_PER_STRUCTURAL_CARD
                        : 0
            const nextResults = [
                ...results,
                { cardId: card.id, coverageRatio, correctBlanks, totalBlanks, correct, xp },
            ]
            setResults(nextResults)
            setCombo((current) => (keptCombo ? current + 1 : 0))
            const nextIndex = index < sessionLength - 1 ? index + 1 : index
            // best-effort, fire-and-forget persistence for resume — never blocks
            // advancing the quiz; still routed through `runGraphQL` (toast on failure,
            // no success toast) rather than a silent catch (teacher 2026-07-11: "FE
            // shouldn't swallow errors, use runGraphQL") — a failed sync only degrades
            // resumability, but the learner should still see it.
            if (sessionId.current) {
                const syncingSessionId = sessionId.current
                void runGraphQL(
                    async () => {
                        const result = await runSyncProgress.trigger({
                            request: {
                                sessionId: syncingSessionId,
                                currentIndex: nextIndex,
                                results: nextResults.map((result) => ({
                                    cardId: result.cardId,
                                    correctBlanks: result.correctBlanks,
                                    totalBlanks: result.totalBlanks,
                                })),
                            },
                            headers: courseHeaders,
                        })
                        return (
                            result.data?.syncFlashcardQuizSessionProgress ?? {
                                success: false,
                                message: t("flashcard.quiz.error"),
                            }
                        )
                    },
                    { showSuccessToast: false },
                )
            }
            if (index < sessionLength - 1) {
                setIndex((current) => current + 1)
            } else {
                void finish(nextResults)
            }
        },
        [card, cloze, results, index, sessionLength, runGraphQL, t, finish, runSyncProgress, courseHeaders],
    )

    // ── RESUMING ─────────────────────────────────────────────────────────
    // reached via the dedicated `/quiz/[sessionId]` route and the rehydrate effect
    // above hasn't landed on `active` yet — show the active-run skeleton instead of
    // flashing the setup screen's tabs/CTA (which would be wrong for this route and
    // never actually shown once the effect commits `active`).
    if (resumeSessionId && phase === "setup" && !resumeError) {
        return <QuizSessionSkeleton className={className} />
    }

    // ── SETUP ────────────────────────────────────────────────────────────
    if (phase === "setup") {
        const resumeData = inProgressSessionSwr.data
        const learnPath = pathConfig().locale(locale).course(displayId).learn()
        return (
            <Box className={className}>
                <StackV gap={6} principle="block-boundary" items={[
                    () => (
                        <TabsCard
                            variant="secondary"
                            className="w-full"
                            leftTabs={{
                                items: [
                                    { key: "begin", label: t("flashcard.quiz.setupTabBegin") },
                                    { key: "history", label: t("flashcard.quiz.setupTabHistory") },
                                    { key: "stats", label: t("flashcard.quiz.setupTabStats") },
                                ],
                                selectedKey: setupTab,
                                ariaLabel: t("flashcard.quiz.setupTabBegin"),
                                onSelectionChange: (key) => setSetupTab(key as "begin" | "history" | "stats"),
                            }}
                        />
                    ),
                    () => (
                        setupTab === "history" ? (
                            <FlashcardQuizHistory courseId={courseId} onStartQuiz={() => setSetupTab("begin")} />
                        ) : setupTab === "stats" ? (
                            <FlashcardQuizStats courseId={courseId} onStartQuiz={() => setSetupTab("begin")} />
                        ) : (
                            <StackV gap={6} items={[
                                ...(resumeData ? [() => {
                                    const resumeRemainingMinutes = Math.max(
                                        0,
                                        Math.ceil((new Date(resumeData.deadlineAt).getTime() - Date.now()) / 60_000),
                                    )
                                    const resumeName = sessionDisplayName(resumeData.name, resumeData.updatedAt, t, locale)
                                    return (
                                        <ContinueCard
                                            title={resumeName}
                                            subtitle={t("flashcard.quiz.resumeSubtitle", {
                                                current: resumeData.currentIndex + 1,
                                                total: resumeData.cardIds.length,
                                                minutes: resumeRemainingMinutes,
                                            })}
                                            urgent={resumeRemainingMinutes <= 15}
                                            variant="hero"
                                            value={resumeData.currentIndex + 1}
                                            max={resumeData.cardIds.length}
                                            ctaLabel={t("flashcard.quiz.resumeCta")}
                                            onPress={() => router.push(learnPath.flashcards().quiz(resumeData.sessionId).build())}
                                        />
                                    )
                                }] : []),
                                ...(resumeError ? [() => <Callout status="danger" title={resumeError} />] : []),
                                () => <FlashcardStatsStrip />,
                                () => (
                                    <LabeledCard label={t("flashcard.quiz.configLabel")}>
                                        <StackV gap={4} principle="group-boundary" items={[
                                            () => (
                                                <StackV gap={3} principle="label-field" items={[
                                                    () => <Label>{t("common.sessionNameLabel")}</Label>,
                                                    () => (
                                                        <TextField variant="secondary" className="w-full">
                                                            <Input
                                                                className="w-full"
                                                                placeholder={t("common.sessionNamePlaceholder")}
                                                                name="sessionName"
                                                                value={sessionName}
                                                                onChange={(event) => setSessionName(event.target.value)}
                                                                maxLength={80}
                                                            />
                                                        </TextField>
                                                    ),
                                                ]} />
                                            ),
                                            () => (
                                                <StackV gap={3} principle="label-field" items={[
                                                    () => <Label>{t("flashcard.quiz.scopeLabel")}</Label>,
                                                    () => (
                                                        <FlexWrapButtonRadio
                                                            ariaLabel={t("flashcard.quiz.scopeLabel")}
                                                            value={scope}
                                                            onChange={setScope}
                                                            items={[
                                                                { value: "all", content: t("flashcard.mode.fullLabel") },
                                                                { value: "due", isDisabled: dueDisabled, content: t("flashcard.mode.dueLabel") },
                                                            ]}
                                                        />
                                                    ),
                                                ]} />
                                            ),
                                            () => (
                                                <StackV gap={3} principle="label-field" items={[
                                                    () => <Label>{t("flashcard.quiz.modeLabel")}</Label>,
                                                    () => (
                                                        <FlexWrapButtonRadio
                                                            ariaLabel={t("flashcard.quiz.modeLabel")}
                                                            value={mode}
                                                            onChange={setMode}
                                                            items={[
                                                                { value: "quick", content: t("flashcard.quiz.modeQuick") },
                                                                { value: "deep", content: t("flashcard.quiz.modeDeep") },
                                                            ]}
                                                        />
                                                    ),
                                                ]} />
                                            ),
                                            () => (
                                                <StackV gap={3} principle="label-field" items={[
                                                    () => <Label>{t("flashcard.quiz.levelLabel")}</Label>,
                                                    () => (
                                                        <FlexWrapButtonRadio
                                                            ariaLabel={t("flashcard.quiz.levelLabel")}
                                                            value={level ?? "all"}
                                                            onChange={(value) => setLevel(value === "all" ? null : value)}
                                                            items={[
                                                                { value: "all", content: t("flashcard.quiz.levelAll") },
                                                                ...LEVELS.map((value) => ({
                                                                    value,
                                                                    content: t(`flashcard.level.${value}`),
                                                                })),
                                                            ]}
                                                        />
                                                    ),
                                                ]} />
                                            ),
                                        ]} />
                                    </LabeledCard>
                                ),
                                () => (
                                    <Button
                                        variant={resumeData ? "secondary" : "primary"}
                                        size="lg"
                                        className="self-start"
                                        isDisabled={!decks || totalCards === 0}
                                        isPending={starting}
                                        onPress={() => { void startSession() }}
                                    >
                                        {t("flashcard.quiz.begin")}
                                        <ArrowRightIcon className="size-5" aria-hidden focusable="false" />
                                    </Button>
                                ),
                                ...(startError ? [() => <Callout status="danger" title={startError} />] : []),
                            ]} />
                        )
                    ),
                ]} />
            </Box>
        )
    }

    // ── RECAP ────────────────────────────────────────────────────────────
    // Transient hand-off only — `finish()` navigates to the dedicated
    // `flashcards/quiz/sessions/[sessionId]/result` route once the completion
    // mutation resolves (2026-07-12: "done" is now answered by the ROUTE, not
    // re-derived client-side here), so this phase never has a real end state
    // to render — just the "saving" interim until that navigation lands.
    if (phase === "recap") {
        return (
            // KEEP the same `WorkSessionHeader` chrome the just-finished ACTIVE
            // phase used (2026-07-12, corrected: the teacher wanted the loading state
            // to render like the active session's header, not swap to
            // `PageHeader` early). Segment bar reads full "done"
            // (`current === total` → every segment `success`), no `rightSlot`
            // (timer no longer meaningful once the run has ended).
            <Box className={className}>
                {(() => {
                    const recapChromeItems = [
                        () => (
                            <WorkSessionHeader
                                backLabel={t("flashcard.exit")}
                                onBack={exitToSetup}
                                title={t("flashcard.mode.quiz")}
                                identity={course?.title ? { name: course.title } : undefined}
                                counter={t("flashcard.quiz.progress", {
                                    current: sessionLength,
                                    total: sessionLength,
                                })}
                                current={sessionLength}
                                total={sessionLength}
                            />
                        ),
                        () => (
                            // teacher-hold: flashcards-remain-quiz-session-body-inset — asymmetric session-body
                            // inset owned via Box page-pad escape hatch (pt-10 not in the padding scale).
                            <Box principle="page-pad" className="px-4 pb-6 pt-10 @app-sm:px-6">
                                <Container size="md" padding={1} body={() => (
                                    <Box className="py-10">
                                        <StackV gap={4} align="center" principle="card-caption" items={[
                                            () => <Spinner size="lg" />,
                                            () => (
                                                <Typography type="body-sm" color="muted">
                                                    {t("flashcard.quiz.result.savingLabel")}
                                                </Typography>
                                            ),
                                        ]} />
                                    </Box>
                                )} />
                            </Box>
                        ),
                    ]
                    return <StackV gap={1} items={recapChromeItems} />
                })()}
            </Box>
        )
    }

    // ── ACTIVE ───────────────────────────────────────────────────────────
    // no cards after the level filter — offer a way back to setup. (A fresh draw
    // that fails to produce cards, or a load failure, is now caught earlier —
    // see `startError` on the setup screen — and never reaches here; this branch
    // is a resume-only guard, e.g. every persisted card was since deleted.)
    if (!card) {
        return (
            <Box className={className}>
                <StackV gap={6} items={[() => (
                    <EmptyState
                        icon={CheckCircleIcon}
                        title={t("flashcard.quiz.emptyAtLevel")}
                        action={() => (
                            <Button size="sm" variant="secondary" onPress={() => setPhase("setup")}>
                                {t("flashcard.quiz.backToSetup")}
                            </Button>
                        )}
                    />
                )]} />
            </Box>
        )
    }

    // shared header: WorkSessionHeader (course identity + step counter +
    // progress segments, combo chip in the right slot) — same shell as the
    // mock-interview's work-surface header. Level/tag chips moved OUT of this
    // header into the question card's own body via `belowFront`/inline (teacher
    // 2026-07-13: "put the quick-quiz chip below the question per the review rules" —
    // matching the same move already done for `FlashcardReviewer`/`DueReview`,
    // per-card meta belongs to the card body, not the fixed session chrome —
    // `components/card.md` Correction 2026-07-13).
    const header = (
        <>
            <WorkSessionHeader
                backLabel={t("flashcard.exit")}
                onBack={() => setConfirmAction("leave")}
                onFinish={() => setConfirmAction("endEarly")}
                finishLabel={t("flashcard.finishEarly")}
                title={t("flashcard.mode.quiz")}
                identity={course?.title ? { name: course.title } : undefined}
                counter={t("flashcard.quiz.progress", {
                    current: index + 1,
                    total: sessionLength,
                })}
                current={index}
                total={sessionLength}
                rightSlot={
                    <StackH gap={4} align="center" classNames={["shrink-0"]} items={[
                        ...(remainingSeconds !== null ? [() => (
                            <StackH
                                gap={3}
                                principle="icon-text"
                                align="center"
                                classNames={["shrink-0"]}
                                items={[
                                    () => <ClockIcon className={cn("size-4", remainingSeconds <= TIME_LIMIT_WARNING_SECONDS && "text-warning-soft-foreground")} aria-hidden focusable="false" />,
                                    () => (
                                        <Typography type="body-sm" weight="medium" className={cn("tabular-nums", remainingSeconds <= TIME_LIMIT_WARNING_SECONDS && "text-warning-soft-foreground")}>
                                            {formatElapsed(remainingSeconds)}
                                        </Typography>
                                    ),
                                ]}
                            />
                        )] : []),
                        ...(combo > 1 ? [() => (
                            <Chip size="sm" variant="soft" color="warning">
                                <FlameIcon className="size-4" aria-hidden focusable="false" />
                                {t("flashcard.quiz.comboChip", { combo })}
                            </Chip>
                        )] : []),
                    ]} />
                }
            />
            <ConfirmDialog
                isOpen={confirmAction !== null}
                onOpenChange={(open) => { if (!open) { setConfirmAction(null) } }}
                title={confirmAction === "leave" ? t("flashcard.leaveTitle") : t("flashcard.finishEarlyTitle")}
                description={confirmAction === "leave" ? t("flashcard.leaveConfirm") : t("flashcard.finishEarlyConfirm")}
                confirmLabel={confirmAction === "leave" ? t("flashcard.leaveCta") : t("flashcard.finishEarlyCta")}
                cancelLabel={t("flashcard.stayIn")}
                onConfirm={() => {
                    const action = confirmAction
                    setConfirmAction(null)
                    if (action === "leave") {
                        exitToSetup()
                    } else if (action === "endEarly") {
                        void finish(results)
                    }
                }}
            />
        </>
    )

    // ── FALLBACK: card has no clozable key terms → plain flip + self-grade ──
    if (!cloze) {
        return (
            <Box className={className}>
                <StackV gap={1} items={[
                    () => header,
                    () => (
                        // teacher-hold: flashcards-remain-quiz-session-body-inset — asymmetric session-body
                        // inset owned via Box page-pad escape hatch (pt-10 not in the padding scale).
                        <Box principle="page-pad" className="px-4 pb-6 pt-10 @app-sm:px-6">
                            <Container size="md" padding={1} body={() => (
                                <StackV gap={6} items={[
                                    () => (
                                        <FlipCard
                                            revealed={showAnswer}
                                            questionLabel={t("flashcard.questionLabel")}
                                            answerLabel={t("flashcard.answerLabel")}
                                            front={() => <MarkdownContent plain markdown={card.question} />}
                                            belowFront={card.level || (card.tags?.length ?? 0) > 0 ? () => {
                                                const level = card.level
                                                return (
                                                    <Cluster gap={3} principle="chip-row" align="center" items={[
                                                        ...(level ? [() => (
                                                            <Chip size="sm" variant="soft" color={LEVEL_COLOR[level] ?? "default"}>
                                                                {t(`flashcard.level.${level}`)}
                                                            </Chip>
                                                        )] : []),
                                                        ...(card.tags ?? []).map((tag) => () => (
                                                            <Chip key={tag} size="sm" variant="soft" color="default">
                                                                {tag}
                                                            </Chip>
                                                        )),
                                                    ]} />
                                                )
                                            } : undefined}
                                            back={() => (
                                                <>
                                                    {card.answer ? (
                                                        <MarkdownContent plain markdown={card.answer} arcSections />
                                                    ) : (
                                                        <Typography type="body-sm" color="muted">
                                                            {t("flashcard.noAnswer")}
                                                        </Typography>
                                                    )}
                                                    {card.explanation ? <MarkdownContent plain markdown={card.explanation} /> : null}
                                                </>
                                            )}
                                        />
                                    ),
                                    ...(showAnswer ? [() => (
                                        <StackV gap={4} principle="label-field" items={[
                                            () => <Label>{t("flashcard.review.rateHint")}</Label>,
                                            () => (
                                                <RatingBar
                                                    options={ratingOptions}
                                                    onRate={(grade) => void commitCard(grade, null)}
                                                    ariaLabel={t("flashcard.review.rateAria")}
                                                    isPending={rating}
                                                />
                                            ),
                                        ]} />
                                    )] : [() => (
                                        <StackH gap={4} principle="flex-action" justify="end" items={[() => (
                                            <Button size="sm" variant="outline" onPress={() => setShowAnswer(true)}>
                                                {t("flashcard.showAnswer")}
                                            </Button>
                                        )]} />
                                    )]),
                                ]} />
                            )} />
                        </Box>
                    ),
                ]} />
            </Box>
        )
    }

    // ── CLOZE: fill blanks → check → read full answer → SM-2 ───────────────
    const allFilled = filled.every((value) => value !== null)
    // `cloze.blanks[blankIndex]?.` guards the same transient-render crash as
    // `filled[segment.index] ?? null` above: for one render tick right after
    // `commitCard` advances to the next card, `cloze` has ALREADY recomputed
    // for it (possibly with FEWER blanks) while `filled`/`checked` still hold
    // the PREVIOUS (possibly longer) card's values — `cloze.blanks[blankIndex]`
    // then reads `undefined` for an out-of-range index, crashing on
    // `.toLowerCase()`. Optional-chaining just makes that comparison `false`
    // for this one tick; the reset effect below realigns everything right after.
    const correctCount = checked
        ? filled.filter((value, blankIndex) =>
            value !== null && value.toLowerCase() === cloze.blanks[blankIndex]?.toLowerCase(),
        ).length
        : 0
    const coverageRatio = cloze.blanks.length > 0 ? correctCount / cloze.blanks.length : 0

    return (
        // scoped per-card (`card.id`) so the word-bank ↔ blank `layoutId` FLIP never
        // leaks its animation into the NEXT card's chips once `cloze` recomputes.
        <LayoutGroup id={`quiz-cloze-${card.id}`}>
            <Box className={className}>
                <StackV gap={1} items={[
                    () => header,
                    () => (
                        // teacher-hold: flashcards-remain-quiz-session-body-inset — asymmetric session-body
                        // inset owned via Box page-pad escape hatch (pt-10 not in the padding scale).
                        <Box principle="page-pad" className="px-4 pb-6 pt-10 @app-sm:px-6">
                            <Container size="md" padding={1} body={() => (
                                <StackV gap={6} items={[
                                    () => (
                                        <StackV gap={4} principle="card-caption" items={[
                                            () => (
                                                <LabeledCard label={t("flashcard.questionLabel")} bordered>
                                                    <MarkdownContent plain markdown={card.question} />
                                                </LabeledCard>
                                            ),
                                            ...(card.level || (card.tags?.length ?? 0) > 0 ? [() => {
                                                const level = card.level
                                                return (
                                                    <Cluster gap={3} principle="chip-row" align="center" items={[
                                                        ...(level ? [() => (
                                                            <Chip size="sm" variant="soft" color={LEVEL_COLOR[level] ?? "default"}>
                                                                {t(`flashcard.level.${level}`)}
                                                            </Chip>
                                                        )] : []),
                                                        ...(card.tags ?? []).map((tag) => () => (
                                                            <Chip key={tag} size="sm" variant="soft" color="default">
                                                                {tag}
                                                            </Chip>
                                                        )),
                                                    ]} />
                                                )
                                            }] : []),
                                        ]} />
                                    ),
                                    () => (
                                        <LabeledCard label={t("flashcard.quiz.fillLabel")} bordered>
                                            <StackV gap={4} principle="sibling-stack" items={[
                                                () => (
                                                    <Typography type="body-xs" weight="medium" color="muted">
                                                        {t("flashcard.quiz.clozeInstruction")}
                                                    </Typography>
                                                ),
                                                () => (
                                                    <p className="text-base leading-loose text-foreground">
                                                        {cloze.segments.map((segment, position) =>
                                                            segment.kind === "text" ? (
                                                                <span key={position}>{segment.text}</span>
                                                            ) : segment.kind === "code" ? (
                                                            // same inline-code styling as MarkdownContent's own renderer
                                                            // (reuseable/MarkdownContent/map.tsx) — kept consistent since this
                                                            // sentence sits right next to the question's own MarkdownContent.
                                                                <code
                                                                    key={position}
                                                                    className="rounded-md bg-default font-mono text-sm text-foreground [overflow-wrap:anywhere]"
                                                                >
                                                                    {segment.text}
                                                                </code>
                                                            ) : segment.kind === "bold" ? (
                                                                <strong key={position} className="font-semibold">{segment.text}</strong>
                                                            ) : segment.kind === "italic" ? (
                                                                <em key={position}>{segment.text}</em>
                                                            ) : (
                                                                (() => {
                                                                    // `?? null` guards a real crash: for one render tick right after
                                                                    // `commitCard` advances `index` (before the card-change effect
                                                                    // resets `filled`), `cloze` has ALREADY recomputed for the new
                                                                    // (possibly longer) card while `filled` still holds the previous
                                                                    // card's (possibly shorter) array — `filled[segment.index]` then
                                                                    // reads `undefined`, which slips past a `!== null` guard and
                                                                    // crashes on `.toLowerCase()`. Coercing to `null` here makes every
                                                                    // downstream `=== null` check treat it the same as "not filled yet".
                                                                    const value = filled[segment.index] ?? null
                                                                    const isCorrect =
                                        checked
                                        && value !== null
                                        && value.toLowerCase() === cloze.blanks[segment.index].toLowerCase()
                                        // empty = dashed-outline "slot" chip, filled surface (canon
                                        // `input.md` §1 — a fill-in affordance sitting on a surface must
                                        // have a real bg-surface fill, never bg-transparent, or it reads
                                        // as a dead patch of the page instead of a field); filled +
                                        // unchecked = solid accent (primary-solid — canon
                                        // `elements/color.md` §3, NOT a `/10` tint); checked = keep the
                                        // existing success/danger tint + shake/pop animation.
                                                                    const chipToneClassName = value === null
                                                                        ? "border border-dashed border-default bg-surface text-muted"
                                                                        : !checked
                                                                            ? "border-0 bg-accent text-accent-foreground"
                                                                            : isCorrect
                                                                                ? "border border-success/60 bg-success-soft text-success-soft-foreground motion-safe:[animation:blankPop_0.35s_ease]"
                                                                                : "border border-danger/60 bg-danger-soft text-danger-soft-foreground motion-safe:[animation:blankShake_0.4s_ease]"
                                                                    // shared `layoutId` with the SAME term's word-bank chip below — when
                                                                    // `placeTerm`/`clearBlank` swaps `value`, framer-motion FLIPs the
                                                                    // chip's bounding box across the two positions ("flies" into/out of
                                                                    // the slot). `undefined` while empty — nothing to morph from/to yet.
                                                                    const layoutId = value !== null ? `quiz-term-${card.id}-${value}` : undefined
                                                                    return (
                                                                        <motion.span
                                                                            key={position}
                                                                            layout
                                                                            layoutId={layoutId}
                                                                            transition={reduceMotion ? { duration: 0 } : CLOZE_CHIP_TRANSITION}
                                                                            className="mx-1 inline-block align-middle"
                                                                        >
                                                                            <button
                                                                                type="button"
                                                                                disabled={checked || value === null}
                                                                                onClick={() => clearBlank(segment.index)}
                                                                                className={!checked && value !== null ? "cursor-pointer" : undefined}
                                                                            >
                                                                                <Chip
                                                                                    size="sm"
                                                                                    // HeroUI bakes `.chip`/`.chip--sm`'s font-size as an
                                                                                    // UNLAYERED style (same trap as radius.md's rounded-*
                                                                                    // warning) — a `text-sm` utility class silently loses
                                                                                    // to it. Only an inline style (always highest
                                                                                    // specificity) actually overrides it; reuse the
                                                                                    // design system's own `--text-sm` token, not a raw px.
                                                                                    // teacher-hold: flashcards-remain-quiz-cloze-vendor-chip-pad
                                                                                    style={{ fontSize: "var(--text-sm)" }}
                                                                                    className={cn(
                                                                                        "min-w-16 justify-center rounded-full font-medium transition-colors",
                                                                                        chipToneClassName,
                                                                                    )}
                                                                                >
                                                                                    {value ?? "···"}
                                                                                </Chip>
                                                                            </button>
                                                                        </motion.span>
                                                                    )
                                                                })()
                                                            ),
                                                        )}
                                                    </p>
                                                ),
                                                ...(checked && correctCount < cloze.blanks.length ? [() => (
                                                    <Typography type="body-xs" color="muted">
                                                        {t("flashcard.quiz.clozeResult", {
                                                            correct: correctCount,
                                                            total: cloze.blanks.length,
                                                        })}
                                                    </Typography>
                                                )] : []),
                                            ]} />
                                        </LabeledCard>
                                    ),
                                    ...(!checked ? [() => (
                                        <StackV gap={6} items={[
                                            () => (
                                                <StackV gap={4} principle="label-field" items={[
                                                    () => <Label>{t("flashcard.quiz.wordBankLabel")}</Label>,
                                                    () => (
                                                        <Cluster gap={3} principle="chip-row" align="center" items={
                                                            cloze.bank
                                                                .filter((term) => !filled.includes(term))
                                                                .map((term) => () => (
                                                                    <motion.button
                                                                        key={term}
                                                                        type="button"
                                                                        layout
                                                                        layoutId={`quiz-term-${card.id}-${term}`}
                                                                        transition={reduceMotion ? { duration: 0 } : CLOZE_CHIP_TRANSITION}
                                                                        onClick={() => placeTerm(term)}
                                                                        className="cursor-pointer transition-transform hover:-translate-y-0.5"
                                                                    >
                                                                        <Chip
                                                                            size="sm"
                                                                            // teacher-hold: flashcards-remain-quiz-cloze-vendor-chip-pad —
                                                                            // HeroUI Chip internal pad, not a sibling layout seam.
                                                                            className="rounded-full border border-default bg-surface text-sm font-medium"
                                                                        >
                                                                            {term}
                                                                        </Chip>
                                                                    </motion.button>
                                                                ))
                                                        } />
                                                    ),
                                                ]} />
                                            ),
                                            () => (
                                                <Button
                                                    variant="primary"
                                                    className="self-start"
                                                    isDisabled={!allFilled}
                                                    onPress={() => setChecked(true)}
                                                >
                                                    {t("flashcard.quiz.checkAnswer")}
                                                </Button>
                                            ),
                                        ]} />
                                    )] : [() => (
                                        <StackV gap={6} items={[
                                            () => (
                                                <StackH gap={3} principle="icon-text" align="center" items={[
                                                    () => (correctCount === cloze.blanks.length ? (
                                                        <CheckCircleIcon className="size-5 text-success-soft-foreground" aria-hidden focusable="false" />
                                                    ) : (
                                                        <XCircleIcon className="size-5 text-danger-soft-foreground" aria-hidden focusable="false" />
                                                    )),
                                                    () => (
                                                        <Typography type="body-sm" weight="medium">
                                                            {t("flashcard.quiz.clozeResult", {
                                                                correct: correctCount,
                                                                total: cloze.blanks.length,
                                                            })}
                                                        </Typography>
                                                    ),
                                                ]} />
                                            ),
                                            ...(showAnswer ? [() => (
                                                <LabeledCard label={t("flashcard.answerLabel")} bordered>
                                                    <StackV gap={4} principle="sibling-stack" items={[
                                                        () => <MarkdownContent plain markdown={card.answer ?? ""} arcSections />,
                                                        ...(card.explanation ? [() => <MarkdownContent plain markdown={card.explanation ?? ""} />] : []),
                                                    ]} />
                                                </LabeledCard>
                                            )] : [() => (
                                                <Button
                                                    variant="outline"
                                                    className="self-start"
                                                    onPress={() => setShowAnswer(true)}
                                                >
                                                    {t("flashcard.quiz.showSolution")}
                                                </Button>
                                            )]),
                                            ...(showAnswer ? [() => (
                                                <StackV gap={4} principle="label-field" items={[
                                                    () => <Label>{t("flashcard.review.rateHint")}</Label>,
                                                    () => (
                                                        <RatingBar
                                                            options={ratingOptions}
                                                            onRate={(grade) => void commitCard(grade, coverageRatio)}
                                                            ariaLabel={t("flashcard.review.rateAria")}
                                                            isPending={rating}
                                                        />
                                                    ),
                                                ]} />
                                            )] : []),
                                        ]} />
                                    )]),
                                ]} />
                            )} />
                        </Box>
                    ),
                ]} />
            </Box>
        </LayoutGroup>
    )
}

import React from "react"
import { MapTrifoldIcon } from "@phosphor-icons/react"
import { MindMapRail, type MindMapRailItem, type MindMapRailTier } from "@/components/blocks/learn/MindMapRail"
import { MindMapContinueButton } from "@/components/blocks/learn/MindMapContinueButton"
import { MindMapFullscreenButton, type MindMapFullscreenButtonAriaLabels } from "@/components/blocks/learn/MindMapFullscreenButton"
import { Legend, type LegendItem } from "@/components/composites/stats/Legend"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { type ComponentTypeWithSkeleton, type SkeletonProps } from "@/components/frames/_slot"
import { ResizableRail } from "@/components/behaviors/ResizableRail"
import { StackH, StackV } from "@/components/frames/Stack"
import { Stage } from "@/components/frames/Stage"
import { ScrollArea } from "@/components/frames/ScrollArea"
import type { CallerIdentity } from "@/components/frames/_identity"

/**
 * SCREEN — `_MindMapPage`: the course keyword graph, in its two real shapes.
 * See the component's own file header for the full function list and the two
 * corrections against the planner's proposed tree (`MindMapBackButton` and
 * `FloatingActionButton` are both absent, on purpose).
 *
 * The graph engine arrives as the `canvas` slot. This screen lays out the rail,
 * the floating chrome and the empty state; it does not know ReactFlow exists.
 *
 * FIVE LEAVES, by STRUCTURE — `workspace` and `standalone` are different
 * compositions (not one shape with a variant flag flipping paint), so each
 * gets its own leaves; `Empty` and `Loading` each lose or swap real nodes
 * (rail's shimmer vs. its populated list; the three floating blocks present
 * vs. absent), which is a structural change, not a data condition of one leaf.
 *
 * PRESENTATIONAL — every input arrives as a prop; the connected `index.tsx`
 * owns the fetch, the rail's filter state, and every `t()` call (`split.md`).
 *
 * Emits its own identity (`data-tier="page"` / `data-component="MindMapPage"`)
 * unconditionally on its root, same as `_ModulePage`/`_ContentPage` — see
 * `split.md`'s "Identity is data-tier + data-component" section.
 *
 * The viewport-relative full-bleed height, the canvas's floating-chrome
 * anchoring, and the rail's scroll region are all composed on `Stage` /
 * `ScrollArea` (`@/components/frames/Stage`, `@/components/frames/ScrollArea`)
 * — the two frames the vocabulary gap this screen flagged in a previous pass
 * was built to close. No raw `className` shape remains on this page.
 */

/** Which shape of the mind map this screen renders — see the file header. */
export type MindMapVariant = "workspace" | "standalone"

/** Props for {@link MindMapPage}. */
export interface MindMapPageProps {
    /** Which shape to render — see the file header for how the two differ. */
    variant: MindMapVariant

    // ── `workspace`: the `MindMapRail` search pane ──
    /** Current search text (controlled). Ignored outside `workspace`. */
    query: string
    /** Fired on every keystroke in the rail's search field. */
    onQuery: (query: string) => void
    /** Current popularity-tier filter. */
    tier: MindMapRailTier
    /** Fired with the tier the reader picked in the rail's funnel popover. */
    onTier: (tier: MindMapRailTier) => void
    /** The current query+tier's matching keywords, in display order. */
    items: Array<MindMapRailItem>
    /** Which result is currently focused on the canvas, if any. */
    selectedId?: string
    /** Fired with a result's id when its rail row is pressed. */
    onPick: (id: string) => void
    /** `true` → the rail's own query/tier fetch is in flight (independent of `isSkeleton`). */
    isRailLoading?: boolean
    /** Accessible name for the rail's search field. */
    railAriaLabel: string
    /** Accessible name for the rail's tier filter group. */
    railTierAriaLabel: string
    /** Accessible name for the rail's drag-to-resize handle. */
    railResizeAriaLabel: string

    // ── `standalone`: floating chrome over the canvas ──
    /** Href of the viewer's next unread lesson/challenge, or `null` when none resolves. Ignored outside `standalone`. */
    resumeHref?: string | null
    /** `true` → the viewer has read everything the map has to offer. */
    allContentDone?: boolean
    /** Fired on a resume press. */
    onResume?: () => void
    /** Accessible name for the resume action. */
    continueAriaLabel?: string
    /** Legend entries — colour swatch + label, e.g. done/in-progress/not-started/locked/current. */
    legendItems?: Array<LegendItem>
    /** Fired on every press of the zoom-in button. */
    onZoomIn?: () => void
    /** Fired on every press of the zoom-out button. */
    onZoomOut?: () => void
    /** Fired on every press of the fullscreen toggle. */
    onToggleFullscreen?: () => void
    /** `true` → canvas is currently fullscreen. */
    isFullscreen?: boolean
    /** Per-button accessible names for the zoom/fullscreen rail. */
    fullscreenAriaLabels?: MindMapFullscreenButtonAriaLabels

    // ── shared ──
    /** `true` → every block that can mirror itself does; the canvas gap swaps to its loading wording. */
    isSkeleton?: boolean
    /** `true` → the course has no authored map/modules yet. `workspace`-ONLY — see the file header. */
    isEmpty?: boolean

    /**
     * The graph itself, mounted by the caller. A screen composes; it does not own a
     * rendering engine — and an earlier pass left a literal placeholder here instead
     * of a slot, which meant wiring this screen would have shipped a mind-map page
     * with no map in it.
     */
    canvas: ComponentTypeWithSkeleton
    /**
     * The empty state's one way forward — browse the course's modules instead.
     * Omit → the empty state states the fact and offers nothing, which is right
     * only when there is nowhere useful to send the reader.
     */
    onBrowseModules?: () => void
    /** Every word the whole-screen empty state says — resolved by the connected half. */
    labels: MindMapPageLabels
}

/** All display text this screen owns, already localized by the connected half. */
export interface MindMapPageLabels {
    /** Heading when the course has no authored map yet. */
    emptyTitle: string
    /** Body when the course has no authored map yet. */
    emptyDescription: string
    /** Label on the empty state's way forward, paired with {@link MindMapPageProps.onBrowseModules}. */
    emptyCta: string
}

/** localStorage key + bounds the real workspace persists the rail width under. */
const RAIL_STORAGE_KEY = "mindmap-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 264
const RAIL_MAX_WIDTH = 520

/** This screen's own identity — handed down to whichever `Stage` is the root, per branch, instead of a wrapping div (BLOCK-2). See `_identity.ts`. */
const MIND_MAP_PAGE_IDENTITY: CallerIdentity = { tier: "page", component: "MindMapPage" }

/**
 * `workspace` empty state — the course has no authored map yet. Replaces the
 * ENTIRE spine, same "one frame + one composite, each badging itself" shape
 * `CourseContents`/`ModulePage` already established for this exact case. The
 * viewport-relative full-bleed height is `Stage`'s `fill="viewport"` — the
 * same shape the real spine below uses for the same reason.
 */
const MindMapWorkspaceEmpty = ({ labels, onBrowseModules }: MindMapWorkspaceEmptyProps) => (
    <Stage
        fill="viewport"
        identity={MIND_MAP_PAGE_IDENTITY}
        canvas={() => (
            <StackV
                gap={1}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                justify="center"
                items={[() => (
                    <AsyncContentEmpty

                        icon={MapTrifoldIcon}
                        title={labels.emptyTitle}
                        description={labels.emptyDescription}
                        onRetry={onBrowseModules}
                        retryLabel={labels.emptyCta}
                    />
                )]}
            />
        )}
    />
)

/**
 * The mind-map screen, in its two shapes. See the file header for the function
 * list, the two corrections against the planner's proposed tree, and the
 * canvas gap.
 *
 * @param props - {@link MindMapPageProps}
 */
const _MindMapPage = ({
    variant,
    query,
    onQuery,
    tier,
    onTier,
    items,
    selectedId,
    onPick,
    isRailLoading = false,
    railAriaLabel,
    railTierAriaLabel,
    railResizeAriaLabel,
    resumeHref = null,
    allContentDone = false,
    onResume,
    continueAriaLabel = "",
    legendItems = [],
    onZoomIn = () => {},
    onZoomOut = () => {},
    onToggleFullscreen = () => {},
    isFullscreen = false,
    fullscreenAriaLabels = { zoomIn: "", zoomOut: "", toggleFullscreen: "" },
    isSkeleton = false,
    isEmpty = false,
    canvas: Canvas,
    onBrowseModules,
    labels,
}: MindMapPageProps) => {
    // Built as a thunk, called only for the non-empty branch below — mirrors
    // `_ModulePage`'s `spine(isSkeleton)`, so the empty branch never pays for
    // building a tree it will not render.
    const workspace = () => {
        const railSection = (
            <MindMapRail

                query={query}
                onQuery={onQuery}
                tier={tier}
                onTier={onTier}
                items={items}
                selectedId={selectedId}
                onPick={onPick}
                isLoading={isRailLoading}
                ariaLabel={railAriaLabel}
                tierAriaLabel={railTierAriaLabel}
                isSkeleton={isSkeleton}

            />
        )

        // The canvas region's floating chrome — in the real app these render as the
        // SAME ReactFlow engine's own Panel children. Only present (`standalone`,
        // resting) — `Stage` skips a slot entirely when it is `undefined`.
        const showOverlays = variant === "standalone" && !isSkeleton

        const topCenterSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    gap={1}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    align="center"
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <MindMapContinueButton

                            resumeHref={resumeHref}
                            allContentDone={allContentDone}
                            onResume={onResume}
                            continueAriaLabel={continueAriaLabel}
                            isSkeleton={isSkeleton}
                        />
                    )]}
                />
            )
            : undefined

        const bottomStartSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    gap={1}
                    isSkeleton={isSkeleton}
                    items={[() => <Legend items={legendItems} />]}
                />
            )
            : undefined

        const bottomEndSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    gap={1}
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <MindMapFullscreenButton

                            onZoomIn={onZoomIn}
                            onZoomOut={onZoomOut}
                            onToggleFullscreen={onToggleFullscreen}
                            isFullscreen={isFullscreen}
                            ariaLabels={fullscreenAriaLabels}
                            isSkeleton={isSkeleton}
                        />
                    )]}
                />
            )
            : undefined

        // The canvas region: the out-of-reach engine's gap, plus (standalone only) the
        // floating chrome that in the real app renders as the SAME engine's own Panel
        // children. `Stage` owns the positioning context and the three floating anchors —
        // no page-level `relative`/`absolute` left.
        const canvasStage = (
            <Stage
                canvas={Canvas}
                topCenter={topCenterSlot}
                bottomStart={bottomStartSlot}
                bottomEnd={bottomEndSlot}
                isSkeleton={isSkeleton}
                classNames={["min-w-0", "flex-1"]}
            />
        )

        const workspaceRail = (
            <ResizableRail
                storageKey={RAIL_STORAGE_KEY}
                defaultWidth={RAIL_DEFAULT_WIDTH}
                minWidth={RAIL_MIN_WIDTH}
                maxWidth={RAIL_MAX_WIDTH}
                ariaLabel={railResizeAriaLabel}
                handleSide="right"
                className="h-full shrink-0 border-r border-default"

            >
                <ScrollArea
                    axis="y"
                    isSkeleton={isSkeleton}
                    body={({ isSkeleton }: SkeletonProps) => (
                        <StackV
                            padding={6}
                            principle="page-pad"
                            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                            gap={1}
                            classNames={["h-full"]}
                            isSkeleton={isSkeleton}
                            items={[() => railSection]}
                        />
                    )}
                />
            </ResizableRail>
        )

        const workspaceSections = (
            <>
                {variant === "workspace" ? workspaceRail : null}
                {canvasStage}
            </>
        )

        // The viewport-relative full-bleed height — the shell's own chrome height
        // subtracted — is `Stage`'s `fill="viewport"`; the rail + canvas row is its
        // `canvas` slot (a stage need not be a literal drawing surface — see the
        // frame's own file header for why this is the shape it names).
        return (
            <Stage
                fill="viewport"
                isSkeleton={isSkeleton}
                identity={MIND_MAP_PAGE_IDENTITY}
                canvas={({ isSkeleton }: SkeletonProps) => (
                    <StackH gap={1} isSkeleton={isSkeleton} items={[() => workspaceSections]} />
                )}
            />
        )
    }

    return variant === "workspace" && isEmpty
        ? <MindMapWorkspaceEmpty labels={labels} onBrowseModules={onBrowseModules} />
        : workspace()
}

export { _MindMapPage }

type MindMapWorkspaceEmptyProps = {
    labels: MindMapPageLabels
    onBrowseModules?: () => void
}

import { InputText } from "@/components/atoms/forms"
import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { CaretRightIcon, GearSixIcon, SparkleIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Breadcrumbs, type BreadcrumbItem } from "@/components/atoms/navigation/Breadcrumbs"
import { Chip } from "@/components/atoms/chips/Chip"

import { Typography } from "@/components/atoms/text/Typography"
import {
    SurfaceCard,
    SurfaceCardAccordion,
    type SurfaceCardAccordionItem,
} from "@/components/composites/cards/SurfaceCard"
import { Callout } from "@/components/composites/feedback/Callout"
import { ListRow } from "@/components/composites/lists/List"
import { PageHeader } from "@/components/composites/layout/Page"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { SplitWorkspace } from "@/components/frames/SplitWorkspace"
import {
    ContentRelatedList,
    type ContentRelatedItem,
} from "@/components/blocks/learn/ContentRelatedList"
import {
    SubmissionScoreCard,
    type AiModelCategory,
} from "@/components/blocks/learn/SubmissionScoreCard"

/**
 * `PersonalProjectTaskPage` — the screen to solve one personal-project task. A
 * screen owns a list of functions. Split workspace: a reading column that swaps
 * per task (task identity, the locked-preview banner, the authored brief or the
 * legacy rubric/implementation guides, and related lessons) beside a
 * persistent, sticky act column (repo URL, the settings-drawer trigger,
 * evaluate/secondary actions, and the latest graded result). Two columns
 * composed with `SplitWorkspace`: a `min-w-0 flex-1` reading column beside a
 * `shrink-0 w-[360px]` sticky aside, stacked on mobile/tablet →
 * `@app-xl:flex-row` on desktop. The grading-settings drawer content is not
 * built — `onOpenSettings` is a chrome trigger only.
 *
 * PRESENTATIONAL — every input arrives as a prop; this twin owns no data of
 * its own, so `index.tsx` IS the presentational file (no separate connected
 * wrapper, no `component.tsx` split) — mirrors `MindMapPage`'s convention.
 *
 * Emits its own identity (`data-tier="page"` / `data-component="PersonalProjectTaskPage"`)
 * unconditionally, handed down to the root `Container` via its `identity` prop
 * (see `frames/_identity.ts`) rather than drawn on a wrapper `div` of its own
 * (`tiers/block.md` BLOCK-2: a page never draws a shape of its own) — same as
 * `split.md`'s "Identity is data-tier + data-component" section. The
 * breadcrumb sits in a `StackH inline` (shrink-to-content sizing) rather
 * than a raw `div`.
 */

/** One personal-project schema-v1 evaluation criterion — the legacy rubric row. */
export interface PersonalProjectTaskLegacyCriterionItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** The criterion sentence itself. */
    text: string
    /** Points this criterion is worth. */
    score: number
    /** Optional grading hint, markdown. Omit → the panel shows a plain "no hint" line. */
    hint?: string
}

/** One legacy per-language implementation guide (schema-v1 tasks with no authored brief). */
export interface PersonalProjectTaskLegacyCodeImplementationItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** Target language label, e.g. "TypeScript". */
    lang: string
    /** How to approach the task in this language, markdown. */
    guide: string
    /** A worked example, markdown. */
    example: string
}

/** The task identity this screen reads about. */
export interface PersonalProjectTaskPageTask {
    /** Task title. */
    title: string
    /** One-paragraph summary of what the task asks for. */
    description?: string
}

/** The schema-v2 authored brief for this task. */
export interface PersonalProjectTaskPageBrief {
    /** The brief itself, markdown, already resolved to the active language/locale. */
    body: string
}

/** Cost/quality tier + model byline data for a graded submission — see {@link SubmissionScoreCard}. */
export interface PersonalProjectSubmissionResult {
    /** Points earned on the latest graded attempt. */
    score: number
    /** Points the attempt was scored out of. */
    maxScore?: number
    /** Whether this score cleared the pass bar. */
    isPassing: boolean
    /** The pass bar itself, in points. */
    passScore?: number
    /** A short line of grader feedback. */
    shortFeedback?: string
    /** The model that produced this grade. */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
    /** Relative time since grading, already localized. */
    timeAgo?: string
}

/** Everything the persistent, sticky act column needs — the project-level submission loop. */
export interface PersonalProjectTaskSubmissionPanelProps {
    /** The GitHub repo URL as typed so far. */
    repoUrl: string
    /** Fired as the learner types the repo URL. */
    onRepoUrlChange: (value: string) => void
    /** Validation message for the repo URL field. Set → the field shows invalid. */
    repoUrlError?: string
    /** Grading language summary shown in the settings row, e.g. "TypeScript". */
    settingsLangLabel: string
    /** Grading branch summary shown in the settings row, e.g. "main". */
    settingsBranch: string
    /** Fired when the settings summary row is pressed — chrome trigger only, see file header. */
    onOpenSettings: () => void
    /** Fired to submit the current repo for AI evaluation. */
    onEvaluate: () => void
    /** `true` → the evaluate CTA shows its own spinner and blocks further presses. */
    isEvaluatePending?: boolean
    /** `true` → the evaluate CTA is disabled (the caller's own combined business rule — locked, syncing, …). */
    isEvaluateDisabled?: boolean
    /** `true` → at least one attempt exists, so the secondary actions unlock and the CTA reads "Re-evaluate". */
    hasAttempts?: boolean
    /** Fired to open the full feedback/result page. */
    onOpenFeedbackDetails: () => void
    /** Fired to open the attempts history drawer. */
    onOpenAttempts: () => void
    /** The latest graded attempt. Present → the score card renders; omit → nothing has been graded yet. */
    result?: PersonalProjectSubmissionResult
}

/** Props for {@link PersonalProjectTaskPage}. */
export interface PersonalProjectTaskPageProps {
    /** Breadcrumb trail as DATA — `PageHeader` builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<BreadcrumbItem>
    /** The task being read/solved. */
    task: PersonalProjectTaskPageTask
    /**
     * `true` → this task is not yet unlocked for the learner (previewing ahead
     * of their current milestone position). Shows the warning banner; nothing
     * else in the reading column changes shape.
     */
    isLocked?: boolean
    /** The schema-v2 authored brief. */
    brief: PersonalProjectTaskPageBrief
    /** Schema-v1 legacy rubric — only present on tasks with no authored brief. */
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    /** Schema-v1 legacy per-language implementation guides — only present alongside {@link legacyCriteria}. */
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    /** Lessons related to this task's subject, auto-derived by the caller from its title/description. */
    relatedItems: Array<ContentRelatedItem>
    /** Section label for {@link relatedItems}, e.g. "You might want to read". */
    relatedLabel: string
    /** Everything the persistent, sticky act column needs. */
    submissionPanelProps: PersonalProjectTaskSubmissionPanelProps
    /**
     * `true` → every part that can mirror itself does. Flows down into the
     * reading column's composed parts and the act column's fields/buttons/score
     * card (§12c) rather than a parallel skeleton tree built here.
     */
    isSkeleton?: boolean
}

/** Skeleton placeholder count for the legacy accordions while real data hasn't landed yet. */
const LEGACY_SKELETON_ROWS = 2

/** `ListRow.leading` for the grading-settings summary row — a gear icon, hidden while skeleton. */
const SettingsLeading = ({ isSkeleton }: SkeletonProps) =>
    isSkeleton ? null : <GearSixIcon aria-hidden focusable="false" className="size-4" />

/** `ListRow.trailing` for the grading-settings summary row — the disclosure chevron. */
const SettingsChevron = () => <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />

/** One markdown body at the `compact` measure the legacy accordion panels use. */
const legacyMarkdown = (body: string) => (
    <MarkdownContent source={body} measure="compact" />
)

/** One legacy code-implementation accordion panel body: guide, then a worked example. */
const legacyCodeBody = (item: PersonalProjectTaskLegacyCodeImplementationItem) => {
    const guideSection = (
        <>
            <Typography size="xs" weight="medium" color="muted" text="Guide" />
            {legacyMarkdown(item.guide)}
        </>
    )
    const exampleSection = (
        <>
            <Typography size="xs" weight="medium" color="muted" text="Example" />
            {legacyMarkdown(item.example)}
        </>
    )
    return (
        <StackV
            gap={4}

            items={[
                () => <StackV gap={2} items={[() => guideSection]} />,
                () => <StackV gap={2} items={[() => exampleSection]} />,
            ]}
        />
    )
}

/**
 * The reading column: task identity (`PageHeader`) + the locked banner + the
 * brief itself + the legacy rubric/implementation guides + related lessons.
 * A private render helper (see file header for why this is not a separate
 * storied component), not an anatomy node of its own.
 */
const readingColumn = (props: {
    breadcrumbItems?: Array<BreadcrumbItem>
    task: PersonalProjectTaskPageTask
    isLocked: boolean
    brief: PersonalProjectTaskPageBrief
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    relatedItems: Array<ContentRelatedItem>
    relatedLabel: string
    isSkeleton: boolean
}) => {
    const {
        breadcrumbItems,
        task,
        isLocked,
        brief,
        legacyCriteria,
        legacyCodeImplementations,
        relatedItems,
        relatedLabel,
        isSkeleton,
    } = props

    const hasLegacyCriteria = (legacyCriteria?.length ?? 0) > 0
    const hasLegacyCode = (legacyCodeImplementations?.length ?? 0) > 0
    const showLegacy = isSkeleton || hasLegacyCriteria || hasLegacyCode
    // Schema-v2 tasks always carry an authored brief; schema-v1 (legacy) tasks
    // hand this screen an empty `body` and rely on the legacy section instead
    // (mirrors `src`'s `TaskBrief` self-hiding when `briefs.length === 0`).
    const showBrief = isSkeleton || brief.body.trim().length > 0

    const criteriaItems: Array<SurfaceCardAccordionItem> = hasLegacyCriteria
        ? (legacyCriteria ?? []).map((item, index) => ({
            id: item.key,
            title: `${index + 1}. ${item.text}`,
            titleEnd: () => <Chip tone="accent" text={`${item.score} points`} />,
            body: () => (
                item.hint
                    ? legacyMarkdown(item.hint)
                    : <Typography size="sm" color="muted"
                        isItalic text="No grading hint yet" />
            ),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `criteria-skeleton-${index}`, title: "", body: () => null }))
            : []

    const codeItems: Array<SurfaceCardAccordionItem> = hasLegacyCode
        ? (legacyCodeImplementations ?? []).map((item) => ({
            id: item.key,
            title: item.lang,
            body: () => legacyCodeBody(item),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `code-skeleton-${index}`, title: "", body: () => null }))
            : []

    const legacyAccordions = (
        <>
            {hasLegacyCriteria || isSkeleton ? (
                <SurfaceCardAccordion
                    variant="nested"
                    items={criteriaItems}
                    allowsMultipleExpanded
                    isSkeleton={isSkeleton}


                />
            ) : null}
            {hasLegacyCode || isSkeleton ? (
                <SurfaceCardAccordion
                    variant="nested"
                    items={codeItems}
                    allowsMultipleExpanded
                    isSkeleton={isSkeleton}


                />
            ) : null}
        </>
    )

    const readingSections = (
        <>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton || breadcrumbItems?.length ? (
                        <StackH
                            inline
                            gap={1}
                            body={() => (
                                <Breadcrumbs collapseOnMobile collapseFrom={4} items={breadcrumbItems ?? []} isSkeleton={isSkeleton} />
                            )}
                        />
                    ) : undefined
                }
                title={task.title}
                description={task.description}
            />

            {!isSkeleton && isLocked ? (
                <Callout
                    status="warning"
                    title="Preview of a task not yet unlocked"
                    description="You need to finish the current task before you can work on this one."

                />
            ) : null}

            {showBrief ? (
                <SurfaceCard
                    label="Guide"
                    isSkeleton={isSkeleton}

                    body={() => <MarkdownContent source={brief.body} />}
                />
            ) : null}

            {showLegacy ? (
                <SurfaceCard
                    label="Evaluation criteria (legacy)"
                    isSkeleton={isSkeleton}

                    body={() => <StackV gap={6} items={[() => legacyAccordions]} />}
                />
            ) : null}

            <ContentRelatedList
                label={relatedLabel}
                items={relatedItems}
                isSkeleton={isSkeleton}

            />
        </>
    )

    return <StackV gap={7} isSkeleton={isSkeleton} items={[() => readingSections]} />
}

/**
 * The persistent, sticky act column: repo URL + settings summary trigger +
 * evaluate/secondary actions + the latest graded result. A private render
 * helper (see file header), not an anatomy node of its own.
 */
const submissionPanel = (props: {
    panel: PersonalProjectTaskSubmissionPanelProps
    isSkeleton: boolean
}) => {
    const { panel, isSkeleton } = props
    const hasAttempts = panel.hasAttempts ?? false

    const evaluateActions = (
        <>
            <Button
                label={hasAttempts ? "Re-evaluate" : "Evaluate"}
                prefixIcon={SparkleIcon}
                onPress={panel.onEvaluate}
                isPending={panel.isEvaluatePending}
                isDisabled={panel.isEvaluateDisabled}
                isSkeleton={isSkeleton}

            />
            <Button
                label="View feedback"
                variant="tertiary"
                onPress={panel.onOpenFeedbackDetails}
                isDisabled={!hasAttempts}
                isSkeleton={isSkeleton}

            />
            <Button
                label="View submission history"
                variant="tertiary"
                onPress={panel.onOpenAttempts}
                isDisabled={!hasAttempts}
                isSkeleton={isSkeleton}

            />
        </>
    )

    const githubFields = (
        <>
            <InputText
                label="GitHub repo URL"
                value={panel.repoUrl}
                onValueChange={panel.onRepoUrlChange}
                errorMessage={panel.repoUrlError}
                placeholder="https://github.com/…"
                ariaLabel="GitHub repo URL"
                isSkeleton={isSkeleton}

            />
            <div>
                <ListRow
                    leading={SettingsLeading}
                    title="Grading settings"
                    meta={() => <Typography size="sm" color="muted" text={`${panel.settingsLangLabel} · ${panel.settingsBranch}`} />}
                    trailing={SettingsChevron}
                    onPress={panel.onOpenSettings}
                    isSkeleton={isSkeleton}

                />
            </div>
            <StackH gap={3} at="sm" principle="flex-action" isSkeleton={isSkeleton} items={[() => evaluateActions]}
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            />
        </>
    )

    const panelSections = (
        <>
            <SurfaceCard
                label="Project GitHub"
                isSkeleton={isSkeleton}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => githubFields]} />}
            />

            {isSkeleton || panel.result != null ? (
                <SubmissionScoreCard
                    label="Latest grading result"
                    score={panel.result?.score ?? 0}
                    maxScore={panel.result?.maxScore}
                    isPassing={panel.result?.isPassing ?? true}
                    passScore={panel.result?.passScore}
                    shortFeedback={panel.result?.shortFeedback}
                    gradedByModel={panel.result?.gradedByModel}
                    modelCategory={panel.result?.modelCategory}
                    timeAgo={panel.result?.timeAgo}
                    isSkeleton={isSkeleton}


                />
            ) : null}
        </>
    )

    return <StackV gap={6} isSkeleton={isSkeleton} items={[() => panelSections]} />
}

/**
 * The personal-project task solve screen. See the file header for the function
 * list, the reuse map, and the two-column layout's known limits.
 *
 * @param props - {@link PersonalProjectTaskPageProps}
 */
const PersonalProjectTaskPage = ({
    breadcrumbItems,
    task,
    isLocked = false,
    brief,
    legacyCriteria,
    legacyCodeImplementations,
    relatedItems,
    relatedLabel,
    submissionPanelProps,
    isSkeleton = false,
}: PersonalProjectTaskPageProps) => (
    <Container
        identity={{ tier: "page", component: "PersonalProjectTaskPage" }}
        size="xl"
        padding={6}
        body={() => (
            <SplitWorkspace

                main={() => readingColumn({
                    breadcrumbItems,
                    task,
                    isLocked,
                    brief,
                    legacyCriteria,
                    legacyCodeImplementations,
                    relatedItems,
                    relatedLabel,
                    isSkeleton,
                })}
                aside={() => submissionPanel({ panel: submissionPanelProps, isSkeleton })}
            />
        )}
    />
)

export { PersonalProjectTaskPage }
